/// Descriptor owner for the completed-abort source-byte witness. An ambiguous
/// close is kept here as an actual unresolved handle and bars every snapshot.
final class EraseAbortCheckedSnapshotIOV1 {
    struct CheckedTreeNode {
        let path: String
        let fact: stat
        let sha256: String?
    }

    private var uncertainDescriptors: [Int32] = []
    private var uncertainDirectories: [UnsafeMutablePointer<DIR>] = []

    func requireSettled() throws {
        guard uncertainDescriptors.isEmpty, uncertainDirectories.isEmpty else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    func retainUncertainDescriptor(_ descriptor: Int32) {
        uncertainDescriptors.append(descriptor)
    }

    func withOpen<Value>(parent: Int32, name: String, flags: Int32,
                         mode: mode_t = 0,
                         _ body: (Int32) throws -> Value) throws -> Value {
        try requireSettled()
        let descriptor = Darwin.openat(parent, name,
            flags | O_NOFOLLOW | O_CLOEXEC, mode)
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        var closeAttempted = false
        do {
            let result = try body(descriptor)
            closeAttempted = true
            guard Darwin.close(descriptor) == 0 else {
                uncertainDescriptors.append(descriptor)
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return result
        } catch {
            if !closeAttempted, Darwin.close(descriptor) != 0 {
                uncertainDescriptors.append(descriptor)
            }
            throw error
        }
    }

    func names(in parent: Int32) throws -> [String] {
        try requireSettled()
        let descriptor = Darwin.openat(parent, ".", O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
        guard descriptor >= 0 else { throw StoreGenerationFailure.dataPointerInvalid }
        guard let directory = Darwin.fdopendir(descriptor) else {
            if Darwin.close(descriptor) != 0 { uncertainDescriptors.append(descriptor) }
            throw StoreGenerationFailure.dataPointerInvalid
        }
        var closeAttempted = false
        do {
            var result = [String]()
            errno = 0
            while let entry = Darwin.readdir(directory) {
                guard let name = OwnedStorageDirectoryEntryNameV1.decode(entry) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                if name != "." && name != ".." { result.append(name) }
                errno = 0
            }
            guard errno == 0 else { throw StoreGenerationFailure.dataPointerInvalid }
            closeAttempted = true
            guard Darwin.closedir(directory) == 0 else {
                uncertainDirectories.append(directory)
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return result.sorted()
        } catch {
            if !closeAttempted, Darwin.closedir(directory) != 0 {
                uncertainDirectories.append(directory)
            }
            throw error
        }
    }

    private func digestFile(_ descriptor: Int32, before: stat) throws -> String {
        var digest = SHA256()
        var count: off_t = 0
        var buffer = [UInt8](repeating: 0, count: 64 * 1024)
        while true {
            let readCount = buffer.withUnsafeMutableBytes {
                Darwin.read(descriptor, $0.baseAddress, $0.count)
            }
            if readCount > 0 {
                count += off_t(readCount)
                guard count <= before.st_size else { throw StoreGenerationFailure.dataPointerInvalid }
                // CryptoKit consumes these bytes synchronously while buffer is pinned.
                // Avoid a fresh Data allocation for each checked 64 KiB read.
                buffer.withUnsafeBytes { rawBuffer in
                    digest.update(bufferPointer: UnsafeRawBufferPointer(
                        start: rawBuffer.baseAddress, count: readCount))
                }
            } else if readCount == 0 { break }
            else if errno != EINTR { throw StoreGenerationFailure.dataPointerInvalid }
        }
        guard count == before.st_size else { throw StoreGenerationFailure.dataPointerInvalid }
        return digest.finalize().map { String(format: "%02x", $0) }.joined()
    }

    func control(parent: Int32, name: String,
                 maximum: Int = 4 * 1024 * 1024) throws -> (Data, String) {
        guard maximum > 0, maximum <= 32 * 1024 * 1024 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try requireSettled()
        func requireNoPending() throws {
            let pendingNames = name == "current.json"
                ? [".current.json.restore-next", ".current.json.migration-next"]
                : [".\(name).restore-next"]
            for pendingName in pendingNames {
                var pending = stat()
                guard Darwin.fstatat(parent, pendingName, &pending,
                                     AT_SYMLINK_NOFOLLOW) != 0, errno == ENOENT else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
        }
        try requireNoPending()
        return try withOpen(parent: parent, name: name,
                            flags: O_RDONLY | O_NONBLOCK) { descriptor in
            var before = stat(), after = stat(), named = stat()
            guard Darwin.fstat(descriptor, &before) == 0,
                  before.st_mode & S_IFMT == S_IFREG,
                  before.st_nlink == 1, before.st_size >= 0,
                  before.st_size <= off_t(maximum),
                  Darwin.fstatat(parent, name, &named, AT_SYMLINK_NOFOLLOW) == 0,
                  named.st_dev == before.st_dev, named.st_ino == before.st_ino else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            var data = Data()
            var buffer = [UInt8](repeating: 0, count: 16 * 1024)
            while true {
                let count = buffer.withUnsafeMutableBytes {
                    Darwin.read(descriptor, $0.baseAddress, $0.count)
                }
                if count > 0 {
                    guard data.count <= maximum - count else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    data.append(contentsOf: buffer.prefix(count))
                } else if count == 0 { break }
                else if errno != EINTR { throw StoreGenerationFailure.dataPointerInvalid }
            }
            guard Darwin.fstat(descriptor, &after) == 0,
                  Darwin.fstatat(parent, name, &named, AT_SYMLINK_NOFOLLOW) == 0,
                  after.st_dev == before.st_dev, after.st_ino == before.st_ino,
                  after.st_size == before.st_size,
                  data.count == Int(before.st_size),
                  after.st_mtimespec.tv_sec == before.st_mtimespec.tv_sec,
                  after.st_mtimespec.tv_nsec == before.st_mtimespec.tv_nsec,
                  after.st_ctimespec.tv_sec == before.st_ctimespec.tv_sec,
                  after.st_ctimespec.tv_nsec == before.st_ctimespec.tv_nsec,
                  named.st_dev == before.st_dev, named.st_ino == before.st_ino else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try requireNoPending()
            let identity = "\(before.st_dev)|\(before.st_ino)|\(before.st_mode)|\(before.st_nlink)|\(before.st_size)|\(before.st_mtimespec.tv_sec)|\(before.st_mtimespec.tv_nsec)|\(before.st_ctimespec.tv_sec)|\(before.st_ctimespec.tv_nsec)"
            return (data, identity)
        }
    }

    /// Adds complete held/named ownership facts to the exact canonical
    /// pointer read. The first `control` also refuses its reserved temporary;
    /// the second held read must be the same bytes and physical inode.
    func originalRecoveryPointerFull(parent: Int32, name: String)
        throws -> (Data, OriginalEraseRecoveryNamespaceSnapshotV1.RegularFact) {
        guard name == "current.json" || name == "retired.json" else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let first = try control(parent: parent, name: name)
        return try withOpen(parent: parent, name: name,
                            flags: O_RDONLY | O_NONBLOCK) { descriptor in
            var held = stat(), named = stat(), after = stat(), namedAfter = stat()
            guard Darwin.fstat(descriptor, &held) == 0,
                  Darwin.fstatat(parent, name, &named,
                      AT_SYMLINK_NOFOLLOW) == 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let fact = try OriginalEraseRecoveryNamespaceSnapshotV1.RegularFact(held)
            guard fact == (try OriginalEraseRecoveryNamespaceSnapshotV1
                    .RegularFact(named)),
                  fact.checkedControlToken == first.1,
                  fact.size <= 4 * 1024 * 1024 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            var bytes = Data()
            var buffer = [UInt8](repeating: 0, count: 16 * 1024)
            while true {
                let count = buffer.withUnsafeMutableBytes {
                    Darwin.read(descriptor, $0.baseAddress, $0.count)
                }
                if count > 0 {
                    guard bytes.count <= 4 * 1024 * 1024 - count else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    bytes.append(contentsOf: buffer.prefix(count))
                } else if count == 0 { break }
                else if errno != EINTR {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            guard Darwin.fstat(descriptor, &after) == 0,
                  Darwin.fstatat(parent, name, &namedAfter,
                      AT_SYMLINK_NOFOLLOW) == 0,
                  fact == (try OriginalEraseRecoveryNamespaceSnapshotV1
                      .RegularFact(after)),
                  fact == (try OriginalEraseRecoveryNamespaceSnapshotV1
                      .RegularFact(namedAfter)),
                  bytes.count == Int(fact.size),
                  bytes == first.0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return (bytes, fact)
        }
    }

    /// The original recovery owner holds EX/G across this read. The caller
    /// supplies the exact node from a checked full-tree walk, so a same-name
    /// replacement cannot be promoted merely by matching returned bytes.
    func sourceBytes(parent: Int32, name: String, node: CheckedTreeNode,
                     maximum: Int64) throws -> Data {
        guard maximum >= 0,
              maximum <= EvidenceCurationLimitsV1.maximumSourceBytes,
              node.fact.st_mode & S_IFMT == S_IFREG,
              node.fact.st_nlink == 1,
              node.fact.st_size >= 0, node.fact.st_size <= maximum,
              let expectedSHA256 = node.sha256 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return try withOpen(parent: parent, name: name,
                            flags: O_RDONLY | O_NONBLOCK) { descriptor in
            var held = stat(), named = stat()
            func requireExact() throws {
                guard Darwin.fstat(descriptor, &held) == 0,
                      Darwin.fstatat(parent, name, &named, AT_SYMLINK_NOFOLLOW) == 0,
                      held.st_dev == node.fact.st_dev,
                      held.st_ino == node.fact.st_ino,
                      held.st_mode == node.fact.st_mode,
                      held.st_nlink == node.fact.st_nlink,
                      held.st_size == node.fact.st_size,
                      held.st_mtimespec.tv_sec == node.fact.st_mtimespec.tv_sec,
                      held.st_mtimespec.tv_nsec == node.fact.st_mtimespec.tv_nsec,
                      held.st_ctimespec.tv_sec == node.fact.st_ctimespec.tv_sec,
                      held.st_ctimespec.tv_nsec == node.fact.st_ctimespec.tv_nsec,
                      named.st_dev == held.st_dev, named.st_ino == held.st_ino else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            try requireExact()
            var result = Data()
            var hasher = SHA256()
            var buffer = [UInt8](repeating: 0, count: 64 * 1024)
            while true {
                let count = buffer.withUnsafeMutableBytes {
                    Darwin.read(descriptor, $0.baseAddress, $0.count)
                }
                if count > 0 {
                    guard Int64(result.count) <= maximum - Int64(count) else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    buffer.withUnsafeBytes { raw in
                        hasher.update(bufferPointer: UnsafeRawBufferPointer(
                            start: raw.baseAddress, count: count))
                    }
                    result.append(contentsOf: buffer.prefix(count))
                } else if count == 0 { break }
                else if errno != EINTR {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            try requireExact()
            guard result.count == Int(node.fact.st_size),
                  hasher.finalize().map({ String(format: "%02x", $0) }).joined()
                    == expectedSHA256 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return result
        }
    }

    /// One classified node under its already checked parent. The file digest
    /// streams through this owner's descriptor; a directory proves its exact
    /// immediate names. All closes remain in withOpen/names quarantine.
    func requirePolicyNode(parent: Int32, name: String,
        expected: OriginalRecoveryProvisionalPolicyV1.Node) throws {
        let directory = expected.sha256 == nil
        let flags = O_RDONLY | O_NONBLOCK | (directory ? O_DIRECTORY : 0)
        try withOpen(parent: parent, name: name, flags: flags) { descriptor in
            var before = stat(), after = stat(), namedBefore = stat(), namedAfter = stat()
            guard Darwin.fstat(descriptor, &before) == 0,
                  Darwin.fstatat(parent, name, &namedBefore,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  expected.matches(before), expected.matches(namedBefore) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            if let expectedSHA = expected.sha256 {
                guard try digestFile(descriptor, before: before) == expectedSHA else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            } else {
                guard try names(in: descriptor) == expected.children else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            guard Darwin.fstat(descriptor, &after) == 0,
                  Darwin.fstatat(parent, name, &namedAfter,
                    AT_SYMLINK_NOFOLLOW) == 0,
                  expected.matches(after), expected.matches(namedAfter) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
    }

    func treeWithNodes(parent: Int32, name: String) throws
        -> (digest: String, nodes: [CheckedTreeNode]) {
        var nodes = [CheckedTreeNode]()
        let digest = try tree(parent: parent, name: name,
            observeTypedNode: { nodes.append($0) })
        return (digest, nodes)
    }

    func tree(parent: Int32, name: String,
              observeNode: ((String, String, [String: String]) -> Void)? = nil,
              observeTypedNode: ((CheckedTreeNode) -> Void)? = nil) throws -> String {
        try requireSettled()
        var tokens = [String]()
        var nodeCount = 0
        var hasModel = false
        func walk(_ parent: Int32, _ name: String, _ path: String, _ depth: Int) throws {
            guard depth <= 64, nodeCount < 100_000 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            nodeCount += 1
            if !path.isEmpty {
                _ = try GenerationOwnedPathV1.classify(path, nodeType: .directory)
            }
            try withOpen(parent: parent, name: name, flags: O_RDONLY | O_DIRECTORY) { directory in
                var before = stat(), namedBefore = stat()
                guard Darwin.fstat(directory, &before) == 0,
                      before.st_mode & S_IFMT == S_IFDIR,
                      Darwin.fstatat(parent, name, &namedBefore, AT_SYMLINK_NOFOLLOW) == 0,
                      namedBefore.st_dev == before.st_dev,
                      namedBefore.st_ino == before.st_ino else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                let initial = try names(in: directory)
                tokens.append("D|\(path)|\(before.st_dev)|\(before.st_ino)|\(before.st_mode)|\(before.st_mtimespec.tv_sec)|\(before.st_mtimespec.tv_nsec)|\(before.st_ctimespec.tv_sec)|\(before.st_ctimespec.tv_nsec)|\(initial.joined(separator: ","))")
                observeTypedNode?(CheckedTreeNode(path: path, fact: before, sha256: nil))
                if let observeNode {
                    observeNode(path, "directory", [
                        "device": String(before.st_dev), "inode": String(before.st_ino),
                        "mode": String(before.st_mode),
                        "mtime": "\(before.st_mtimespec.tv_sec).\(before.st_mtimespec.tv_nsec)",
                        "ctime": "\(before.st_ctimespec.tv_sec).\(before.st_ctimespec.tv_nsec)",
                        "membership": initial.joined(separator: "\u{0}")
                    ])
                }
                for child in initial {
                    guard !child.isEmpty, child != ".", child != "..",
                          !child.contains("/") else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    let childPath = path.isEmpty ? child : "\(path)/\(child)"
                    var named = stat()
                    guard Darwin.fstatat(directory, child, &named, AT_SYMLINK_NOFOLLOW) == 0 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    if named.st_mode & S_IFMT == S_IFDIR {
                        try walk(directory, child, childPath, depth + 1)
                    } else if named.st_mode & S_IFMT == S_IFREG {
                        nodeCount += 1
                        guard nodeCount < 100_000, named.st_nlink == 1 else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                        _ = try GenerationOwnedPathV1.classify(childPath, nodeType: .regularFile)
                        if childPath == "model.sqlite" { hasModel = true }
                        try withOpen(parent: directory, name: child,
                                     flags: O_RDONLY | O_NONBLOCK) { file in
                            var start = stat(), end = stat(), renamed = stat()
                            guard Darwin.fstat(file, &start) == 0,
                                  start.st_mode & S_IFMT == S_IFREG,
                                  start.st_nlink == 1,
                                  start.st_dev == named.st_dev,
                                  start.st_ino == named.st_ino,
                                  start.st_size == named.st_size,
                                  start.st_size >= 0 else {
                                throw StoreGenerationFailure.dataPointerInvalid
                            }
                            let hash = try digestFile(file, before: start)
                            guard Darwin.fstat(file, &end) == 0,
                                  Darwin.fstatat(directory, child, &renamed, AT_SYMLINK_NOFOLLOW) == 0,
                                  end.st_dev == start.st_dev, end.st_ino == start.st_ino,
                                  end.st_size == start.st_size, end.st_nlink == start.st_nlink,
                                  end.st_mtimespec.tv_sec == start.st_mtimespec.tv_sec,
                                  end.st_mtimespec.tv_nsec == start.st_mtimespec.tv_nsec,
                                  end.st_ctimespec.tv_sec == start.st_ctimespec.tv_sec,
                                  end.st_ctimespec.tv_nsec == start.st_ctimespec.tv_nsec,
                                  renamed.st_dev == start.st_dev, renamed.st_ino == start.st_ino else {
                                throw StoreGenerationFailure.dataPointerInvalid
                            }
                            tokens.append("F|\(childPath)|\(start.st_dev)|\(start.st_ino)|\(start.st_mode)|\(start.st_nlink)|\(start.st_size)|\(start.st_mtimespec.tv_sec)|\(start.st_mtimespec.tv_nsec)|\(start.st_ctimespec.tv_sec)|\(start.st_ctimespec.tv_nsec)|\(hash)")
                            observeTypedNode?(CheckedTreeNode(
                                path: childPath, fact: start, sha256: hash))
                            if let observeNode {
                                observeNode(childPath, "file", [
                                    "device": String(start.st_dev), "inode": String(start.st_ino),
                                    "mode": String(start.st_mode), "nlink": String(start.st_nlink),
                                    "size": String(start.st_size),
                                    "mtime": "\(start.st_mtimespec.tv_sec).\(start.st_mtimespec.tv_nsec)",
                                    "ctime": "\(start.st_ctimespec.tv_sec).\(start.st_ctimespec.tv_nsec)",
                                    "sha256": hash
                                ])
                            }
                        }
                    } else { throw StoreGenerationFailure.dataPointerInvalid }
                }
                var after = stat(), namedAfter = stat()
                guard try names(in: directory) == initial,
                      Darwin.fstat(directory, &after) == 0,
                      Darwin.fstatat(parent, name, &namedAfter, AT_SYMLINK_NOFOLLOW) == 0,
                      after.st_dev == before.st_dev, after.st_ino == before.st_ino,
                      after.st_mtimespec.tv_sec == before.st_mtimespec.tv_sec,
                      after.st_mtimespec.tv_nsec == before.st_mtimespec.tv_nsec,
                      after.st_ctimespec.tv_sec == before.st_ctimespec.tv_sec,
                      after.st_ctimespec.tv_nsec == before.st_ctimespec.tv_nsec,
                      namedAfter.st_dev == before.st_dev, namedAfter.st_ino == before.st_ino else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
        }
        try walk(parent, name, "", 0)
        guard hasModel else { throw StoreGenerationFailure.dataGenerationMissing }
        try requireSettled()
        return StoreMigrationCanonicalJSONV1.sha256(Data(tokens.sorted().joined(separator: "\n").utf8))
    }

    /// Read a deletion cut against the immutable complete roster. Unlike the
    /// original generation walk this remains defined after model.sqlite has
    /// been unlinked. It observes all survivors, then admits only one exact
    /// postorder prefix of absent nodes; it never learns a replacement tree.
    func schema2ColdRosterCut(
        parent: Int32, generationName: String,
        generation: EraseSchema2ColdDeletionRosterV1.Generation,
        generationURL: URL,
        retainUncertainDescriptor: (Int32) -> Void,
        checkPolicy: Bool = true
    ) throws -> (deletedCount: Int, observedSHA256: String) {
        try requireSettled()
        guard generation.state == "present",
              generation.generationID == generationName,
              UUID(uuidString: generationName)?.uuidString.lowercased()
                == generationName,
              let nodes = generation.nodes,
              let deletionOrder = generation.deletionOrder,
              !nodes.isEmpty,
              nodes.first?.path == "",
              nodes.first?.kind == "directory",
              deletionOrder.count == nodes.count else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        var expected: [String: EraseSchema2ColdDeletionRosterV1.Node] = [:]
        for node in nodes {
            guard expected.updateValue(node, forKey: node.path) == nil else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        guard expected.count == nodes.count,
              Set(deletionOrder) == Set(expected.keys) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        func fullFact(_ lhs: stat, _ rhs: stat) -> Bool {
            lhs.st_dev == rhs.st_dev && lhs.st_ino == rhs.st_ino &&
            lhs.st_mode == rhs.st_mode && lhs.st_nlink == rhs.st_nlink &&
            lhs.st_size == rhs.st_size &&
            lhs.st_mtimespec.tv_sec == rhs.st_mtimespec.tv_sec &&
            lhs.st_mtimespec.tv_nsec == rhs.st_mtimespec.tv_nsec &&
            lhs.st_ctimespec.tv_sec == rhs.st_ctimespec.tv_sec &&
            lhs.st_ctimespec.tv_nsec == rhs.st_ctimespec.tv_nsec
        }
        var observed: [String: (stat, String?)] = [:]
        func walk(_ parentFD: Int32, _ name: String,
            _ path: String, _ depth: Int) throws {
            guard depth <= 64,
                  let node = expected[path],
                  node.kind == "directory" else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            try withOpen(parent: parentFD, name: name,
                flags: O_RDONLY | O_DIRECTORY) { directory in
                var before = stat(), namedBefore = stat()
                guard Darwin.fstat(directory, &before) == 0,
                      Darwin.fstatat(parentFD, name, &namedBefore,
                        AT_SYMLINK_NOFOLLOW) == 0,
                      before.st_mode & S_IFMT == S_IFDIR,
                      fullFact(before, namedBefore),
                      observed[path] == nil else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                observed[path] = (before, nil)
                let children = try names(in: directory)
                for child in children {
                    guard !child.isEmpty, child != ".", child != "..",
                          !child.contains("/") else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    let childPath = path.isEmpty ? child
                        : "\(path)/\(child)"
                    guard let expectedChild = expected[childPath] else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    switch expectedChild.kind {
                    case "directory":
                        try walk(directory, child, childPath, depth + 1)
                    case "regular":
                        try withOpen(parent: directory, name: child,
                            flags: O_RDONLY | O_NONBLOCK) { file in
                            var first = stat(), named = stat(), last = stat()
                            guard Darwin.fstat(file, &first) == 0,
                                  Darwin.fstatat(directory, child, &named,
                                    AT_SYMLINK_NOFOLLOW) == 0,
                                  first.st_mode & S_IFMT == S_IFREG,
                                  first.st_nlink == 1,
                                  fullFact(first, named),
                                  observed[childPath] == nil else {
                                throw StoreGenerationFailure.dataPointerInvalid
                            }
                            let sha = try digestFile(file, before: first)
                            guard Darwin.fstat(file, &last) == 0,
                                  Darwin.fstatat(directory, child, &named,
                                    AT_SYMLINK_NOFOLLOW) == 0,
                                  fullFact(first, last),
                                  fullFact(last, named) else {
                                throw StoreGenerationFailure.dataPointerInvalid
                            }
                            observed[childPath] = (last, sha)
                        }
                    default:
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                }
                var after = stat(), namedAfter = stat()
                guard try names(in: directory) == children,
                      Darwin.fstat(directory, &after) == 0,
                      Darwin.fstatat(parentFD, name, &namedAfter,
                        AT_SYMLINK_NOFOLLOW) == 0,
                      fullFact(before, after),
                      fullFact(after, namedAfter) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
        }
        var namedRoot = stat()
        if Darwin.fstatat(parent, generationName, &namedRoot,
                AT_SYMLINK_NOFOLLOW) != 0 {
            guard errno == ENOENT else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        } else {
            try walk(parent, generationName, "", 0)
        }
        let missing = Set(expected.keys).subtracting(observed.keys)
        let missingCount = missing.count
        guard missingCount <= deletionOrder.count,
              Set(deletionOrder.prefix(missingCount)) == missing else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        for (path, (fact, sha)) in observed {
            guard let node = expected[path],
                  node.device >= 0,
                  node.device <= Int64(dev_t.max),
                  node.inode <= UInt64(ino_t.max),
                  node.mode <= UInt32(mode_t.max),
                  node.links <= UInt64(nlink_t.max),
                  fact.st_dev == dev_t(node.device),
                  fact.st_ino == ino_t(node.inode),
                  fact.st_mode == mode_t(node.mode) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            if node.kind == "regular" {
                guard fact.st_nlink == nlink_t(node.links),
                      fact.st_size == off_t(node.size),
                      fact.st_mtimespec.tv_sec == node.mtimeSeconds,
                      fact.st_mtimespec.tv_nsec == node.mtimeNanoseconds,
                      fact.st_ctimespec.tv_sec == node.ctimeSeconds,
                      fact.st_ctimespec.tv_nsec == node.ctimeNanoseconds,
                      sha == node.sha256 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            } else {
                let prefix = path.isEmpty ? "" : path + "/"
                let removedDirect = missing.compactMap { candidate -> String? in
                    guard candidate.hasPrefix(prefix),
                          candidate != path else { return nil }
                    let suffix = String(candidate.dropFirst(prefix.count))
                    return !suffix.isEmpty && !suffix.contains("/")
                        ? candidate : nil
                }
                let removedDirectories = removedDirect.filter {
                    expected[$0]?.kind == "directory"
                }.count
                guard node.links >= UInt64(removedDirectories),
                      fact.st_nlink == nlink_t(
                        node.links - UInt64(removedDirectories)),
                      fact.st_size >= 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                if removedDirect.isEmpty {
                    guard fact.st_size == off_t(node.size),
                          fact.st_mtimespec.tv_sec == node.mtimeSeconds,
                          fact.st_mtimespec.tv_nsec == node.mtimeNanoseconds,
                          fact.st_ctimespec.tv_sec == node.ctimeSeconds,
                          fact.st_ctimespec.tv_nsec == node.ctimeNanoseconds else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                }
            }
        }
        let observedTokens = observed.keys.sorted().compactMap { path
            -> String? in
            guard let (fact, sha) = observed[path] else { return nil }
            return "\(path)|\(fact.st_dev)|\(fact.st_ino)|\(fact.st_mode)|\(fact.st_nlink)|\(fact.st_size)|\(fact.st_mtimespec.tv_sec)|\(fact.st_mtimespec.tv_nsec)|\(fact.st_ctimespec.tv_sec)|\(fact.st_ctimespec.tv_nsec)|\(sha ?? "")"
        }
        guard observedTokens.count == observed.count else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let observedSHA256 = StoreMigrationCanonicalJSONV1.sha256(
            Data(observedTokens.joined(separator: "\n").utf8))
        guard generationURL.isFileURL,
              generationURL.lastPathComponent == generationName else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        var policyCloseUncertain = false
        if checkPolicy { for path in observed.keys.sorted() {
            guard let (fact, _) = observed[path],
                  let node = expected[path] else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let kind: OwnedFileKindV1 = path.isEmpty
                ? .durableDirectory
                : try GenerationOwnedPathV1.classify(path,
                    nodeType: node.kind == "directory"
                        ? .directory : .regularFile).kind
            let url = path.isEmpty ? generationURL
                : generationURL.appendingPathComponent(path,
                    isDirectory: node.kind == "directory")
            let policy = try ProtectedFilePolicyV1
                .observeTemporalPolicyWithCheckedClose(kind, at: url,
                    retainUncertainDescriptor: { descriptor in
                        policyCloseUncertain = true
                        retainUncertainDescriptor(descriptor)
                    })
            guard !policyCloseUncertain,
                  policy.state == .strictComplete,
                  policy.device == UInt64(fact.st_dev),
                  policy.inode == UInt64(fact.st_ino),
                  policy.linkCount == UInt64(fact.st_nlink) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        } }
        try requireSettled()
        if checkPolicy {
            let after = try schema2ColdRosterCut(parent: parent,
                generationName: generationName,
                generation: generation,
                generationURL: generationURL,
                retainUncertainDescriptor: retainUncertainDescriptor,
                checkPolicy: false)
            guard after.deletedCount == missingCount,
                  after.observedSHA256 == observedSHA256 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        return (missingCount, observedSHA256)
    }

    /// Nonmutating, checked-close walk of an exact owner-held directory tree.
    /// Every transient descriptor remains here on an ambiguous close. This is
    /// intentionally independent of the generation-only path classifier.
    func postRetiredTree(parent: Int32, name: String,
        excluding excludedPaths: Set<String> = [],
        ignoringDirectoryMetadata ignoredDirectories: Set<String> = [],
        observedRootLinks: ((UInt64) -> Void)? = nil,
        normalizingSingleTargetManifestRootLinksFrom sourceRootLinks: UInt64? = nil,
        normalizingSingleRemovedFileDirectoryLinksFrom removedFile: (
            path: String, excludedChild: String, sourceLinks: UInt64)? = nil,
        observeNode: ((String, String, String, [String]?, String?) -> Void)? = nil,
        observeTypedNode: ((CheckedTreeNode, [String]?) -> Void)? = nil
    ) throws -> String {
        try requireSettled()
        if let removedFile {
            guard !removedFile.path.isEmpty,
                  !removedFile.excludedChild.isEmpty,
                  !removedFile.excludedChild.contains("/"),
                  removedFile.sourceLinks >= 2,
                  ignoredDirectories.contains(removedFile.path),
                  excludedPaths == Set([removedFile.path + "/"
                    + removedFile.excludedChild]) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        var tokens: [String] = []
        var nodeCount = 0
        var totalBytes: Int64 = 0
        var removedFileDirectorySeen = false
        // Directory names are adversarial UTF-8. Hex framing makes every
        // path and entry injective even when a name contains our token
        // separators, commas, newlines, or digits.
        func encoded(_ value: String) -> String {
            value.utf8.map { String(format: "%02x", $0) }.joined()
        }
        func nodeFact(_ value: stat) -> String {
            "\(value.st_dev)|\(value.st_ino)|\(value.st_mode)|\(value.st_nlink)|\(value.st_size)|\(value.st_mtimespec.tv_sec)|\(value.st_mtimespec.tv_nsec)|\(value.st_ctimespec.tv_sec)|\(value.st_ctimespec.tv_nsec)"
        }
        func stableDirectoryFact(_ value: stat, path: String) throws -> String {
            if ignoredDirectories.contains(path) {
                let links: UInt64
                if let removedFile, path == removedFile.path {
                    guard UInt64(value.st_nlink) == removedFile.sourceLinks - 1 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    links = removedFile.sourceLinks
                    removedFileDirectorySeen = true
                } else {
                    links = path.isEmpty
                        ? sourceRootLinks ?? UInt64(value.st_nlink)
                        : UInt64(value.st_nlink)
                }
                return "\(value.st_dev)|\(value.st_ino)|\(value.st_mode)|\(links)"
            }
            return nodeFact(value)
        }
        func walk(_ parent: Int32, _ name: String, _ path: String, _ depth: Int) throws {
            guard depth <= 64, nodeCount < 100_000 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            nodeCount += 1
            try withOpen(parent: parent, name: name,
                         flags: O_RDONLY | O_DIRECTORY) { directory in
                var before = stat(), named = stat()
                guard Darwin.fstat(directory, &before) == 0,
                      before.st_mode & S_IFMT == S_IFDIR,
                      Darwin.fstatat(parent, name, &named, AT_SYMLINK_NOFOLLOW) == 0,
                      named.st_dev == before.st_dev, named.st_ino == before.st_ino,
                      named.st_mode & S_IFMT == S_IFDIR else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                if path.isEmpty {
                    observedRootLinks?(UInt64(before.st_nlink))
                    if let sourceRootLinks = sourceRootLinks {
                        guard ignoredDirectories.contains(""),
                              excludedPaths.count == 1,
                              sourceRootLinks < UInt64.max,
                              UInt64(before.st_nlink) == sourceRootLinks + 1 else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                    }
                }
                let entries = try names(in: directory)
                let visible = entries.filter { entry in
                    let child = path.isEmpty ? entry : "\(path)/\(entry)"
                    return !excludedPaths.contains(child)
                }
                let directoryFact = try stableDirectoryFact(before, path: path)
                tokens.append("D|\(encoded(path))|\(directoryFact)|\(visible.map(encoded).joined(separator: ","))")
                observeNode?(path, "directory", directoryFact, visible, nil)
                observeTypedNode?(CheckedTreeNode(path: path, fact: before,
                    sha256: nil), visible)
                for entry in visible {
                    guard !entry.isEmpty, entry != ".", entry != "..",
                          !entry.contains("/") else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    let childPath = path.isEmpty ? entry : "\(path)/\(entry)"
                    var child = stat()
                    guard Darwin.fstatat(directory, entry, &child,
                                         AT_SYMLINK_NOFOLLOW) == 0 else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                    switch child.st_mode & S_IFMT {
                    case S_IFDIR:
                        try walk(directory, entry, childPath, depth + 1)
                    case S_IFREG:
                        nodeCount += 1
                        guard nodeCount < 100_000, child.st_nlink == 1,
                              child.st_size >= 0, child.st_size <= 1_073_741_824,
                              totalBytes <= 1_073_741_824 - Int64(child.st_size) else {
                            throw StoreGenerationFailure.dataPointerInvalid
                        }
                        totalBytes += Int64(child.st_size)
                        try withOpen(parent: directory, name: entry,
                                     flags: O_RDONLY | O_NONBLOCK) { file in
                            var start = stat(), end = stat(), namedAfter = stat()
                            guard Darwin.fstat(file, &start) == 0,
                                  start.st_mode & S_IFMT == S_IFREG,
                                  start.st_nlink == 1,
                                  start.st_dev == child.st_dev,
                                  start.st_ino == child.st_ino,
                                  start.st_size == child.st_size else {
                                throw StoreGenerationFailure.dataPointerInvalid
                            }
                            let digest = try digestFile(file, before: start)
                            guard Darwin.fstat(file, &end) == 0,
                                  Darwin.fstatat(directory, entry, &namedAfter,
                                                AT_SYMLINK_NOFOLLOW) == 0,
                                  nodeFact(start) == nodeFact(end),
                                  nodeFact(start) == nodeFact(namedAfter) else {
                                throw StoreGenerationFailure.dataPointerInvalid
                            }
                            let fileFact = nodeFact(start)
                            tokens.append("F|\(encoded(childPath))|\(fileFact)|\(digest)")
                            observeNode?(childPath, "file", fileFact, nil, digest)
                            observeTypedNode?(CheckedTreeNode(path: childPath,
                                fact: start, sha256: digest), nil)
                        }
                    default:
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
                }
                var after = stat(), namedAfter = stat()
                guard try names(in: directory) == entries,
                      Darwin.fstat(directory, &after) == 0,
                      Darwin.fstatat(parent, name, &namedAfter,
                                    AT_SYMLINK_NOFOLLOW) == 0,
                      nodeFact(before) == nodeFact(after),
                      nodeFact(before) == nodeFact(namedAfter) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
        }
        try walk(parent, name, "", 0)
        if removedFile != nil, !removedFileDirectorySeen {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try requireSettled()
        return StoreMigrationCanonicalJSONV1.sha256(
            Data(tokens.sorted().joined(separator: "\n").utf8))
    }

}

/// The maintenance eligibility probe must not construct the ordinary Restore
/// authority: that constructor may create and protect missing directories.
/// This owner opens only already-existing names and keeps any ambiguous close
/// in its checked I/O owner. The Router retains it before the first open.
final class RestoreMaintenanceClearObservationV1 {
    enum EmptyRootFailure: Error {
        case restoreGenerations
        case importStaging
    }
    struct DirectoryFact: Equatable {
        let device: dev_t
        let inode: ino_t
        let mode: mode_t
        let links: nlink_t
        let size: off_t
        let modifiedSeconds: Int64
        let modifiedNanoseconds: Int64
        let changedSeconds: Int64
        let changedNanoseconds: Int64

        init(_ value: stat) throws {
            guard value.st_mode & S_IFMT == S_IFDIR else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            device = value.st_dev
            inode = value.st_ino
            mode = value.st_mode
            links = value.st_nlink
            size = value.st_size
            modifiedSeconds = Int64(value.st_mtimespec.tv_sec)
            modifiedNanoseconds = Int64(value.st_mtimespec.tv_nsec)
            changedSeconds = Int64(value.st_ctimespec.tv_sec)
            changedNanoseconds = Int64(value.st_ctimespec.tv_nsec)
        }
    }

    /// Captured while the actual opened reader is live and before Router
    /// recovery. A later maintenance probe compares every control byte and
    /// physical fact to this value; it never adopts a failed state as a new
    /// baseline.
    struct Frame: Equatable {
        let generationID: UUID
        let workspaceID: WorkspaceID
        let replicaID: ReplicaID
        let storeSchemaRelease: PersistentSchemaReleaseV1
        let generationManifestSHA256: String
        let intendedPointer: Data?
        let support: DirectoryFact
        let data: DirectoryFact
        let generations: DirectoryFact
        let operations: DirectoryFact
        let operationsNames: [String]
        let operationsChildFacts: [String: DirectoryFact]
        let migration: DirectoryFact
        let current: Data
        let currentIdentity: String
        let retired: Data
        let retiredIdentity: String
        let manifest: Data
        let manifestIdentity: String
        let installedNames: [String]
        let migrationNames: [String]
    }

    /// Typed output of one actual journal-root constructor. Its parent and
    /// child facts are read from the constructor's held descriptors before it
    /// releases them; an after-failure filesystem scan cannot mint this value.
    struct OperationsChildReceipt {
        let name: String
        let created: Bool
        let parent: DirectoryFact
        let child: DirectoryFact
    }

    /// The held journal owner advances its own physical cursor after each
    /// exact mutation. This is a provenance-bearing result, not a fresh
    /// filesystem scan offered as a new expected frame.
    struct OperationsRecoveryReceipt {
        let name: String
        let initialChild: DirectoryFact
        let finalChild: DirectoryFact
        let mutationCount: Int
    }

    private let root: URL
    private let expectedRoot: StoreApplicationSupportIdentity
    private let io = EraseAbortCheckedSnapshotIOV1()
    private var attempted = false

    init(applicationSupportURL: URL, expectedRoot: StoreApplicationSupportIdentity) throws {
        root = applicationSupportURL.standardizedFileURL
        guard root.isFileURL else { throw StoreGenerationFailure.dataPointerInvalid }
        self.expectedRoot = expectedRoot
    }

    var hasUncertainClose: Bool { (try? io.requireSettled()) == nil }

    private func fact(_ descriptor: Int32) throws -> DirectoryFact {
        var value = stat()
        guard Darwin.fstat(descriptor, &value) == 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return try DirectoryFact(value)
    }

    private func namedFact(parent: Int32, name: String) throws -> DirectoryFact {
        var value = stat()
        guard Darwin.fstatat(parent, name, &value, AT_SYMLINK_NOFOLLOW) == 0 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return try DirectoryFact(value)
    }

    private func withExistingDirectory<Value>(
        parent: Int32, name: String, _ body: (Int32) throws -> Value
    ) throws -> Value {
        try io.withOpen(parent: parent, name: name, flags: O_RDONLY | O_DIRECTORY) { descriptor in
            let before = try fact(descriptor)
            guard try namedFact(parent: parent, name: name) == before else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            let value = try body(descriptor)
            guard try fact(descriptor) == before,
                  try namedFact(parent: parent, name: name) == before else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return value
        }
    }

    private func requireAbsent(parent: Int32, name: String) throws {
        var value = stat()
        guard Darwin.fstatat(parent, name, &value, AT_SYMLINK_NOFOLLOW) != 0,
              errno == ENOENT else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    private func requireNoEraseAuthority(parent: Int32) throws -> DirectoryFact? {
        var value = stat()
        if Darwin.fstatat(parent, "FieldEvidenceErase", &value, AT_SYMLINK_NOFOLLOW) != 0 {
            guard errno == ENOENT else { throw StoreGenerationFailure.dataPointerInvalid }
            try requireAbsent(parent: parent, name: "FieldEvidenceErase")
            return nil
        }
        return try withExistingDirectory(parent: parent, name: "FieldEvidenceErase") { erase in
            guard try io.names(in: erase).isEmpty else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return try fact(erase)
        }
    }

#if DEBUG
    /// Reports only fixed predicate results from the already-read control bytes.
    /// It does not observe the filesystem again or change the failing guard.
    private func reportPointerSemanticMismatch(
        current: Data, retired: Data, generationID: UUID,
        workspaceID: WorkspaceID, replicaID: ReplicaID,
        storeSchemaRelease: PersistentSchemaReleaseV1,
        generationManifestSHA256: String, intendedPointer: Data?
    ) {
        let pointer: CurrentGenerationPointerV3?
        if let decoded = try? CurrentPointerCodecV1.decode(current),
           case .v3(let value, _) = decoded {
            pointer = value
        } else { pointer = nil }
        let retiredValue = try? JSONDecoder().decode(RetiredPointerV1.self,
            from: retired)
        let retiredIDs = retiredValue?.generationIDs ?? []
        let pointerID = pointer?.generationID
        let categories = [
            "pointerV3=\(pointer != nil)",
            "pointerCanonical=\(pointer.flatMap { try? $0.canonicalData() } == current)",
            "generation=\(pointerID == generationID.uuidString.lowercased())",
            "workspace=\(pointer?.workspaceID == workspaceID.rawValue.uuidString.lowercased())",
            "replica=\(pointer?.replicaID == replicaID.rawValue.uuidString.lowercased())",
            "schema=\(pointer?.storeSchemaVersion == storeSchemaRelease.versionIdentifier.major)",
            "manifest=\(pointer?.generationManifestSHA256 == generationManifestSHA256)",
            "intended=\(intendedPointer.map { $0 == current } ?? true)",
            "retiredDecode=\(retiredValue != nil)",
            "retiredCanonical=\(retiredValue.flatMap { try? StoreMigrationCanonicalJSONV1.encode($0) } == retired)",
            "retiredSorted=\(retiredValue != nil && retiredIDs == retiredIDs.sorted())",
            "retiredUnique=\(retiredValue != nil && Set(retiredIDs).count == retiredIDs.count)",
            "retiredUUIDs=\(retiredValue != nil && retiredIDs.allSatisfy { UUID(uuidString: $0)?.uuidString.lowercased() == $0 })",
            "retiredExcludesCurrent=\(retiredValue != nil && (pointerID.map { !retiredIDs.contains($0) } ?? false))"
        ]
        FileHandle.standardError.write(Data(
            "V23_RESTORE_POINTER_SEMANTICS_V1 \(categories.joined(separator: " "))\n".utf8))
    }
#endif

    private func scanControls(
        generationID: UUID,
        workspaceID: WorkspaceID,
        replicaID: ReplicaID,
        storeSchemaRelease: PersistentSchemaReleaseV1,
        generationManifestSHA256: String,
        intendedPointer: Data?
    ) throws -> Frame {
        try withExistingDirectory(parent: AT_FDCWD, name: root.path) { app in
#if DEBUG
            print("V23_RESTORE_MAINTENANCE_FRAME_V1 stage=root-open-complete")
#endif
            let support = try fact(app)
            guard support.device == expectedRoot.device,
                  support.inode == expectedRoot.inode else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            return try withExistingDirectory(parent: app,
                name: "FieldEvidenceData") { dataFD in
#if DEBUG
                print("V23_RESTORE_MAINTENANCE_FRAME_V1 stage=data-open-complete")
#endif
                let data = try fact(dataFD)
                let (current, currentIdentity) = try io.control(
                    parent: dataFD, name: "current.json")
                let (retired, retiredIdentity) = try io.control(
                    parent: dataFD, name: "retired.json")
#if DEBUG
                print("V23_RESTORE_MAINTENANCE_FRAME_V1 stage=pointer-controls-complete")
#endif
                guard case .v3(let pointer, _) = try CurrentPointerCodecV1.decode(current),
                      try pointer.canonicalData() == current,
                      pointer.generationID == generationID.uuidString.lowercased(),
                      pointer.workspaceID == workspaceID.rawValue.uuidString.lowercased(),
                      pointer.replicaID == replicaID.rawValue.uuidString.lowercased(),
                      pointer.storeSchemaVersion == storeSchemaRelease.versionIdentifier.major,
                      pointer.generationManifestSHA256 == generationManifestSHA256,
                      intendedPointer.map({ $0 == current }) ?? true,
                      let retiredValue = try? JSONDecoder().decode(
                        RetiredPointerV1.self, from: retired),
                      try StoreMigrationCanonicalJSONV1.encode(retiredValue) == retired,
                      retiredValue.generationIDs == retiredValue.generationIDs.sorted(),
                      Set(retiredValue.generationIDs).count
                        == retiredValue.generationIDs.count,
                      retiredValue.generationIDs.allSatisfy({
                        UUID(uuidString: $0)?.uuidString.lowercased() == $0
                      }),
                      !retiredValue.generationIDs.contains(pointer.generationID) else {
#if DEBUG
                    reportPointerSemanticMismatch(current: current, retired: retired,
                        generationID: generationID, workspaceID: workspaceID,
                        replicaID: replicaID, storeSchemaRelease: storeSchemaRelease,
                        generationManifestSHA256: generationManifestSHA256,
                        intendedPointer: intendedPointer)
#endif
                    throw StoreGenerationFailure.dataPointerInvalid
                }
#if DEBUG
                print("V23_RESTORE_POINTER_SEMANTICS_V1 stage=guard-complete")
#endif
                try StorePointerSchemaRegistry.requireRetired(retiredValue.schemaVersion)
#if DEBUG
                print("V23_RESTORE_MAINTENANCE_FRAME_V1 stage=pointer-semantics-complete")
#endif
                let expectedNames = ([pointer.generationID]
                    + retiredValue.generationIDs).sorted()
                return try withExistingDirectory(parent: dataFD,
                    name: "generations") { generationsFD in
                    let generations = try fact(generationsFD)
                    let installedNames = try io.names(in: generationsFD)
                    guard installedNames == expectedNames else {
                        throw StoreGenerationFailure.dataPointerInvalid
                    }
#if DEBUG
                    print("V23_RESTORE_MAINTENANCE_FRAME_V1 stage=installed-names-complete")
#endif
                    return try withExistingDirectory(parent: app,
                        name: "FieldEvidenceOperations") { operationsFD in
                        let operations = try fact(operationsFD)
                        let operationsNames = try io.names(in: operationsFD)
                        var operationsChildFacts = [String: DirectoryFact]()
                        for child in ["finalization", "deletion"] where operationsNames.contains(child) {
                            operationsChildFacts[child] = try withExistingDirectory(
                                parent: operationsFD, name: child) { try fact($0) }
                        }
                        return try withExistingDirectory(parent: operationsFD,
                            name: "schema-migration") { migrationFD in
                            let migration = try fact(migrationFD)
                            let migrationNames = try io.names(in: migrationFD)
#if DEBUG
                            print("V23_RESTORE_MAINTENANCE_FRAME_V1 stage=migration-open-complete")
#endif
                            let manifestName = "manifest-"
                                + generationID.uuidString.lowercased() + ".json"
                            guard migrationNames.contains(manifestName) else {
                                throw StoreGenerationFailure.dataPointerInvalid
                            }
                            let (manifest, manifestIdentity) = try io.control(
                                parent: migrationFD, name: manifestName,
                                maximum: 32 * 1024 * 1024)
                            let decoded = try StoreGenerationManifestV1
                                .decodeCanonical(from: manifest)
#if DEBUG
                            print("V23_RESTORE_MAINTENANCE_FRAME_V1 stage=manifest-read-complete")
#endif
                            guard StoreMigrationCanonicalJSONV1.sha256(manifest)
                                    == generationManifestSHA256,
                                  decoded.generationID == generationID,
                                  decoded.storeSchemaRelease == storeSchemaRelease else {
                                throw StoreGenerationFailure.dataPointerInvalid
                            }
#if DEBUG
                            print("V23_RESTORE_MAINTENANCE_FRAME_V1 stage=manifest-semantic-complete")
#endif
                            return Frame(generationID: generationID,
                                workspaceID: workspaceID,
                                replicaID: replicaID,
                                storeSchemaRelease: storeSchemaRelease,
                                generationManifestSHA256: generationManifestSHA256,
                                intendedPointer: intendedPointer,
                                support: support, data: data,
                                generations: generations,
                                operations: operations,
                                operationsNames: operationsNames,
                                operationsChildFacts: operationsChildFacts,
                                migration: migration,
                                current: current, currentIdentity: currentIdentity,
                                retired: retired, retiredIdentity: retiredIdentity,
                                manifest: manifest,
                                manifestIdentity: manifestIdentity,
                                installedNames: installedNames,
                                migrationNames: migrationNames)
                        }
                    }
                }
            }
        }
    }

    @MainActor
    func captureFrame(session: StoreGenerationSession,
        intendedPointer: Data? = nil) throws -> Frame {
        guard !attempted, let epoch = session.generationEpoch,
              epoch.generationID == session.generationID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        attempted = true
        let frame = try scanControls(generationID: session.generationID,
            workspaceID: session.workspaceID,
            replicaID: session.replicaID,
            storeSchemaRelease: session.storeSchemaRelease,
            generationManifestSHA256: epoch.generationManifestSHA256,
            intendedPointer: intendedPointer)
        try io.requireSettled()
        return frame
    }

    /// Everything except the one authenticated Operations parent transition
    /// stays bound to the immutable pre-effect frame.
    private func sameOriginalControls(_ lhs: Frame, _ rhs: Frame) -> Bool {
        lhs.generationID == rhs.generationID
            && lhs.workspaceID == rhs.workspaceID
            && lhs.replicaID == rhs.replicaID
            && lhs.storeSchemaRelease == rhs.storeSchemaRelease
            && lhs.generationManifestSHA256 == rhs.generationManifestSHA256
            && lhs.intendedPointer == rhs.intendedPointer
            && lhs.support == rhs.support
            && lhs.data == rhs.data
            && lhs.generations == rhs.generations
            && lhs.migration == rhs.migration
            && lhs.current == rhs.current
            && lhs.currentIdentity == rhs.currentIdentity
            && lhs.retired == rhs.retired
            && lhs.retiredIdentity == rhs.retiredIdentity
            && lhs.manifest == rhs.manifest
            && lhs.manifestIdentity == rhs.manifestIdentity
            && lhs.installedNames == rhs.installedNames
            && lhs.migrationNames == rhs.migrationNames
    }

    /// Called immediately before an actual journal-root constructor, without
    /// an await or a second owner. A failed check never refreshes the expected
    /// frame.
    func requireBeforeOperationsEffect(matching expected: Frame) throws {
        let actual = try scanControls(generationID: expected.generationID,
            workspaceID: expected.workspaceID,
            replicaID: expected.replicaID,
            storeSchemaRelease: expected.storeSchemaRelease,
            generationManifestSHA256: expected.generationManifestSHA256,
            intendedPointer: expected.intendedPointer)
        guard actual == expected else { throw StoreGenerationFailure.dataPointerInvalid }
        try io.requireSettled()
    }

    /// The only accepted parent change is the exact child created or reopened
    /// by the retained constructor named by `receipt`. The constructor's
    /// held/named postimage, not this scan, supplies the expected successor.
    func recordOperationsEffect(original: Frame, previous: Frame,
        receipt: OperationsChildReceipt) throws -> Frame {
        guard receipt.name == "finalization" || receipt.name == "deletion",
              previous.operationsNames.contains(receipt.name) != receipt.created else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let observed = try scanControls(generationID: original.generationID,
            workspaceID: original.workspaceID,
            replicaID: original.replicaID,
            storeSchemaRelease: original.storeSchemaRelease,
            generationManifestSHA256: original.generationManifestSHA256,
            intendedPointer: original.intendedPointer)
        var expectedNames = previous.operationsNames
        if receipt.created { expectedNames.append(receipt.name); expectedNames.sort() }
        guard sameOriginalControls(observed, original),
              observed.operationsNames == expectedNames,
              observed.operations.device == previous.operations.device,
              observed.operations.inode == previous.operations.inode,
              observed.operations.mode == previous.operations.mode,
              observed.operations == receipt.parent,
              observed.operationsChildFacts[receipt.name] == receipt.child,
              previous.operationsChildFacts.filter({ $0.key != receipt.name })
                == observed.operationsChildFacts.filter({ $0.key != receipt.name }) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        if !receipt.created {
            guard previous.operationsChildFacts[receipt.name]?.device == receipt.child.device,
                  previous.operationsChildFacts[receipt.name]?.inode == receipt.child.inode,
                  previous.operationsChildFacts[receipt.name]?.mode == receipt.child.mode else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        }
        try io.requireSettled()
        return observed
    }

    func recordOperationsRecoveryEffect(original: Frame, previous: Frame,
        receipt: OperationsRecoveryReceipt) throws -> Frame {
        guard receipt.name == "finalization" || receipt.name == "deletion",
              let priorChild = previous.operationsChildFacts[receipt.name],
              priorChild == receipt.initialChild,
              receipt.mutationCount >= 0,
              receipt.finalChild.device == priorChild.device,
              receipt.finalChild.inode == priorChild.inode,
              receipt.finalChild.mode == priorChild.mode else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let observed = try scanControls(generationID: original.generationID,
            workspaceID: original.workspaceID,
            replicaID: original.replicaID,
            storeSchemaRelease: original.storeSchemaRelease,
            generationManifestSHA256: original.generationManifestSHA256,
            intendedPointer: original.intendedPointer)
        guard sameOriginalControls(observed, original),
              observed.operations == previous.operations,
              observed.operationsNames == previous.operationsNames,
              observed.operationsChildFacts[receipt.name] == receipt.finalChild,
              previous.operationsChildFacts.filter({ $0.key != receipt.name })
                == observed.operationsChildFacts.filter({ $0.key != receipt.name }) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try io.requireSettled()
        return observed
    }

    /// A maintenance option is displayed only after the original frame is
    /// proved around the entire clear-journal observation. All opens are
    /// exact-existing and checked-close owned by this retained observer.
    func requireClear(matching frame: Frame,
        expectedOperations: Frame? = nil,
        validatedImport: ValidatedV4BackupPackageV1? = nil,
        onStage: (String) -> Void) throws {
        guard !attempted else { throw StoreGenerationFailure.dataPointerInvalid }
        attempted = true
#if DEBUG
        print("V23_RESTORE_MAINTENANCE_FRAME_V1 stage=before-scan-enter")
#endif
        let before = try scanControls(generationID: frame.generationID,
            workspaceID: frame.workspaceID,
            replicaID: frame.replicaID,
            storeSchemaRelease: frame.storeSchemaRelease,
            generationManifestSHA256: frame.generationManifestSHA256,
            intendedPointer: frame.intendedPointer)
#if DEBUG
        if before != frame {
            print("V23_RESTORE_MAINTENANCE_FRAME_V1 mismatch "
                + "support=\(before.support == frame.support) "
                + "data=\(before.data == frame.data) "
                + "generations=\(before.generations == frame.generations) "
                + "operations=\(before.operations == frame.operations) "
                + "operationsDevice=\(before.operations.device == frame.operations.device) "
                + "operationsInode=\(before.operations.inode == frame.operations.inode) "
                + "operationsMode=\(before.operations.mode == frame.operations.mode) "
                + "operationsLinks=\(before.operations.links == frame.operations.links) "
                + "operationsSize=\(before.operations.size == frame.operations.size) "
                + "operationsModifiedSeconds=\(before.operations.modifiedSeconds == frame.operations.modifiedSeconds) "
                + "operationsModifiedNanoseconds=\(before.operations.modifiedNanoseconds == frame.operations.modifiedNanoseconds) "
                + "operationsChangedSeconds=\(before.operations.changedSeconds == frame.operations.changedSeconds) "
                + "operationsChangedNanoseconds=\(before.operations.changedNanoseconds == frame.operations.changedNanoseconds) "
                + "migration=\(before.migration == frame.migration) "
                + "currentBytes=\(before.current == frame.current) "
                + "currentIdentity=\(before.currentIdentity == frame.currentIdentity) "
                + "retiredBytes=\(before.retired == frame.retired) "
                + "retiredIdentity=\(before.retiredIdentity == frame.retiredIdentity) "
                + "manifestBytes=\(before.manifest == frame.manifest) "
                + "manifestIdentity=\(before.manifestIdentity == frame.manifestIdentity) "
                + "installedNames=\(before.installedNames == frame.installedNames) "
                + "migrationNames=\(before.migrationNames == frame.migrationNames)")
        }
#endif
        guard sameOriginalControls(before, frame),
              before.operations == (expectedOperations ?? frame).operations,
              before.operationsNames == (expectedOperations ?? frame).operationsNames,
              before.operationsChildFacts == (expectedOperations ?? frame).operationsChildFacts else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
#if DEBUG
        print("V23_RESTORE_MAINTENANCE_FRAME_V1 stage=before-scan-equal")
#endif
        try requireClearRoots(validatedImport: validatedImport,
            onStage: onStage)
#if DEBUG
        print("V23_RESTORE_MAINTENANCE_FRAME_V1 stage=after-scan-enter")
#endif
        let after = try scanControls(generationID: frame.generationID,
            workspaceID: frame.workspaceID,
            replicaID: frame.replicaID,
            storeSchemaRelease: frame.storeSchemaRelease,
            generationManifestSHA256: frame.generationManifestSHA256,
            intendedPointer: frame.intendedPointer)
#if DEBUG
        if after != frame {
            print("V23_RESTORE_MAINTENANCE_FRAME_V1 mismatch "
                + "support=\(after.support == frame.support) "
                + "data=\(after.data == frame.data) "
                + "generations=\(after.generations == frame.generations) "
                + "operations=\(after.operations == frame.operations) "
                + "operationsDevice=\(after.operations.device == frame.operations.device) "
                + "operationsInode=\(after.operations.inode == frame.operations.inode) "
                + "operationsMode=\(after.operations.mode == frame.operations.mode) "
                + "operationsLinks=\(after.operations.links == frame.operations.links) "
                + "operationsSize=\(after.operations.size == frame.operations.size) "
                + "operationsModifiedSeconds=\(after.operations.modifiedSeconds == frame.operations.modifiedSeconds) "
                + "operationsModifiedNanoseconds=\(after.operations.modifiedNanoseconds == frame.operations.modifiedNanoseconds) "
                + "operationsChangedSeconds=\(after.operations.changedSeconds == frame.operations.changedSeconds) "
                + "operationsChangedNanoseconds=\(after.operations.changedNanoseconds == frame.operations.changedNanoseconds) "
                + "migration=\(after.migration == frame.migration) "
                + "currentBytes=\(after.current == frame.current) "
                + "currentIdentity=\(after.currentIdentity == frame.currentIdentity) "
                + "retiredBytes=\(after.retired == frame.retired) "
                + "retiredIdentity=\(after.retiredIdentity == frame.retiredIdentity) "
                + "manifestBytes=\(after.manifest == frame.manifest) "
                + "manifestIdentity=\(after.manifestIdentity == frame.manifestIdentity) "
                + "installedNames=\(after.installedNames == frame.installedNames) "
                + "migrationNames=\(after.migrationNames == frame.migrationNames)")
        }
#endif
        guard sameOriginalControls(after, frame),
              after.operations == (expectedOperations ?? frame).operations,
              after.operationsNames == (expectedOperations ?? frame).operationsNames,
              after.operationsChildFacts == (expectedOperations ?? frame).operationsChildFacts else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
#if DEBUG
        print("V23_RESTORE_MAINTENANCE_FRAME_V1 stage=after-scan-equal")
#endif
        try io.requireSettled()
    }

    func requireClear(onStage: (String) -> Void) throws {
        guard !attempted else { throw StoreGenerationFailure.dataPointerInvalid }
        attempted = true
        try requireClearRoots(onStage: onStage)
        try io.requireSettled()
    }

    /// A validated import is the sole prospective child created after the
    /// original empty-stage maintenance proof. Its name and original physical
    /// identity come from the real import result, never from a later scan.
    private func admittedImportName(
        _ package: ValidatedV4BackupPackageV1?
    ) throws -> String? {
        guard let package else { return nil }
        let staged = package.stagedPackageURL.standardizedFileURL
        let expectedParent = root
            .appendingPathComponent("FieldEvidenceRestore", isDirectory: true)
            .appendingPathComponent("staging", isDirectory: true)
        let name = staged.lastPathComponent
        let suffix = ".fieldrecordbackup"
        guard staged.isFileURL,
              staged.deletingLastPathComponent() == expectedParent,
              package.members.rootURL.standardizedFileURL == staged,
              name.hasSuffix(suffix),
              let id = UUID(uuidString: String(name.dropLast(suffix.count))),
              name == id.uuidString.lowercased() + suffix else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return name
    }

    private func requireClearRoots(
        validatedImport: ValidatedV4BackupPackageV1? = nil,
        onStage: (String) -> Void
    ) throws {
        let admittedName = try admittedImportName(validatedImport)
        try withExistingDirectory(parent: AT_FDCWD, name: root.path) { app in
            let held = try fact(app)
            guard held.device == expectedRoot.device,
                  held.inode == expectedRoot.inode else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            // These two exact-existing children are also required by the
            // ordinary Restore authority; neither may be reconstructed here.
            try withExistingDirectory(parent: app, name: "FieldEvidenceData") { data in
                try withExistingDirectory(parent: data, name: "generations") { _ in
                    onStage("erase")
                    let erase = try requireNoEraseAuthority(parent: app)
                    try withExistingDirectory(parent: app, name: "FieldEvidenceRestore") { restore in
                        onStage("restore")
                        try requireAbsent(parent: restore, name: "restore.json")
                        try requireAbsent(parent: restore, name: ".restore.json.next")
                        try withExistingDirectory(parent: restore, name: "generations") { generations in
                            onStage("generation-names")
                            guard try io.names(in: generations).isEmpty else {
                                throw EmptyRootFailure.restoreGenerations
                            }
                            try withExistingDirectory(parent: restore, name: "staging") { staging in
                                onStage("import-names")
                                let names = try io.names(in: staging)
                                if let admittedName, let validatedImport {
                                    guard names == [admittedName] else {
                                        throw EmptyRootFailure.importStaging
                                    }
                                    try withExistingDirectory(parent: staging,
                                        name: admittedName) { staged in
                                        let actual = try fact(staged)
                                        guard actual.device == validatedImport.members.rootIdentity.device,
                                              actual.inode == validatedImport.members.rootIdentity.inode else {
                                            throw StoreGenerationFailure.dataPointerInvalid
                                        }
                                    }
                                } else {
                                    guard names.isEmpty else {
                                        throw EmptyRootFailure.importStaging
                                    }
                                }
                                try requireAbsent(parent: restore, name: "restore.json")
                                try requireAbsent(parent: restore, name: ".restore.json.next")
                                guard try requireNoEraseAuthority(parent: app) == erase else {
                                    throw StoreGenerationFailure.dataPointerInvalid
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

#if DEBUG
struct ErasePostRetiredGenerationSnapshotV1: Equatable {
    let current: Data
    let currentIdentity: String
    let retired: Data
    let retiredIdentity: String
    let installedNames: [String]
    let treeDigests: [String: String]
    let dataRootDigest: String
}

struct EraseCompletedAbortNodeFactV1: Equatable {
    let nodeType: String
    let fields: [String: String]
}

struct EraseCompletedAbortSourceBytesV1: Equatable {
    let current: Data
    let currentIdentity: String
    let retired: Data
    let retiredIdentity: String
    let sourceTreeDigest: String
    /// DEBUG diagnosis only. These facts come from the same checked tree walk
    /// as sourceTreeDigest; authoritative equality remains the five facts above.
    let sourceNodes: [String: EraseCompletedAbortNodeFactV1]

    static func == (lhs: Self, rhs: Self) -> Bool {
        lhs.current == rhs.current
            && lhs.currentIdentity == rhs.currentIdentity
            && lhs.retired == rhs.retired
            && lhs.retiredIdentity == rhs.retiredIdentity
            && lhs.sourceTreeDigest == rhs.sourceTreeDigest
    }
}

/// Value-only identity of one SQLite input in the original, held generation.
/// The private copy is allowed to create its own WAL index; it never uses a
/// pathname supplied by the caller to select source bytes.
struct EraseCompletedAbortSQLiteFileV1: Equatable {
    let name: String
    let byteCount: UInt64
    let sha256: String
    let physicalIdentity: String
}

struct EraseCompletedAbortCanonicalSourceV1: Equatable {
    let workspaceIdentity: WorkspaceReplicaIdentityV1
    // Commits to every V3...V53 local canonical envelope in order, with
    // domain, release, layer index, byte length and final layer count.
    let canonicalRowsFramedSHA256: String
    let mutationHistory: MutationHistorySnapshotV1
}
struct EraseOriginalColdExitControlsV1: Equatable {
    let current: Data
    let currentIdentity: String
    let retired: Data
    let retiredIdentity: String
}
#endif

/// Closed original-recovery SQLite input under the retained V949 owner.
struct OriginalRecoverySQLiteFileV1: Equatable {
    let name: String
    let byteCount: UInt64
    let sha256: String
    let physicalIdentity: String
}

private struct RestoreSourceTreeNodeFactV1 {
    let kind: String
    let fields: [String]
    let entries: [String]?
    let digest: String?
}

enum RestoreSourceTreeProbeStageV1: Equatable {
    case pointerAttestation
    case maintenanceSource
    case activationBeforeTarget
    case targetPhysical
    case readerClose
    case other

    var label: String {
        switch self {
        case .pointerAttestation: return "pointer-attestation"
        case .maintenanceSource: return "maintenance-source"
        case .activationBeforeTarget: return "activation-before-target"
        case .targetPhysical: return "target-physical"
        case .readerClose: return "reader-close"
        case .other: return "other"
        }
    }
}

/// Original Restore source owner. Router retains this value before its first
/// descriptor opens, but it never retains the old SwiftData session, context,
/// container, or Coordinator. The old tree's immutable byte/identity digest
/// remains the baseline across every service effect and the reader drain.
@MainActor
final class RestoreSourceReaderExitV1 {
    private let factory: StoreGenerationFactory
    let registry: GenerationLeaseRegistryV1
    let reader: GenerationLeaseHandleV1
    let sourceGenerationID: UUID
    private let applicationSupportURL: URL
    private weak var observedSession: StoreGenerationSession?
    private weak var observedContext: ModelContext?
    private weak var observedContainer: ModelContainer?
    private weak var observedCoordinator: StoreSessionCoordinator?
    private let io = EraseAbortCheckedSnapshotIOV1()
    private var supportDescriptor: Int32 = -1
    private var dataDescriptor: Int32 = -1
    private var generationsDescriptor: Int32 = -1
    private var supportIdentity: (dev_t, ino_t)?
    private var dataIdentity: (dev_t, ino_t)?
    private var generationsIdentity: (dev_t, ino_t)?
    private var sourceTreeDigest: String?
    // Facts are captured by the same checked walk as sourceTreeDigest. A
    // post-alias exception may compare only the exact SHM ctime pair; every
    // other node fact and content digest must remain bound to this baseline.
    private var originalSourceTreeFacts: [String: RestoreSourceTreeNodeFactV1]?
    private var preAliasTargetGenerationID: UUID?
    private var preAliasTargetPointer: Data?
    private var postAliasSHMCtime: (seconds: String, nanoseconds: String)?
    private var originalCurrent: Data?
    private var originalRetired: Data?
    private enum State: Equatable { case unobserved, captured, closing, uncertain, closed }
    private var state = State.unobserved

    init(session: StoreGenerationSession, sourceContext: ModelContext,
         coordinator: StoreSessionCoordinator?,
         factory: StoreGenerationFactory) throws {
        guard session.modelContext === sourceContext,
              session.generationRootURL.standardizedFileURL
                == factory.installedGenerationURL(id: session.generationID)
                    .standardizedFileURL else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let reader = try session.retainedReaderForOriginalRestoreTransition(
            factory: factory)
        self.factory = factory
        self.registry = try factory.makeGenerationLeaseRegistry()
        self.reader = reader
        self.sourceGenerationID = session.generationID
        self.applicationSupportURL = factory.restoreApplicationSupportURL
        observedSession = session
        observedContext = sourceContext
        observedContainer = sourceContext.container
        observedCoordinator = coordinator
    }

    private static func identity(_ descriptor: Int32) throws -> (dev_t, ino_t) {
        var value = stat()
        guard Darwin.fstat(descriptor, &value) == 0,
              value.st_mode & S_IFMT == S_IFDIR else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        return (value.st_dev, value.st_ino)
    }

    private static func requireNamedDirectory(parent: Int32, name: String,
        identity: (dev_t, ino_t)) throws {
        var value = stat()
        guard Darwin.fstatat(parent, name, &value, AT_SYMLINK_NOFOLLOW) == 0,
              value.st_mode & S_IFMT == S_IFDIR,
              value.st_dev == identity.0, value.st_ino == identity.1 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    private func requireHeldRoots() throws {
        guard supportDescriptor >= 0, dataDescriptor >= 0,
              generationsDescriptor >= 0,
              let supportIdentity, let dataIdentity,
              let generationsIdentity else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let support = try Self.identity(supportDescriptor)
        let data = try Self.identity(dataDescriptor)
        let generations = try Self.identity(generationsDescriptor)
        var namedSupport = stat()
        guard support == supportIdentity, data == dataIdentity,
              generations == generationsIdentity,
              Darwin.lstat(applicationSupportURL.path, &namedSupport) == 0,
              namedSupport.st_mode & S_IFMT == S_IFDIR,
              namedSupport.st_dev == supportIdentity.0,
              namedSupport.st_ino == supportIdentity.1 else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try Self.requireNamedDirectory(parent: supportDescriptor,
            name: "FieldEvidenceData", identity: dataIdentity)
        try Self.requireNamedDirectory(parent: dataDescriptor,
            name: "generations", identity: generationsIdentity)
    }

    /// The Router stores this object before calling capturePhysical(). Every
    /// successful open is transferred to a field before the next throw.
    func capturePhysical() throws {
        guard state == .unobserved else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        do {
            supportDescriptor = Darwin.open(applicationSupportURL.path,
                O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
            guard supportDescriptor >= 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            supportIdentity = try Self.identity(supportDescriptor)
            dataDescriptor = Darwin.openat(supportDescriptor,
                "FieldEvidenceData", O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
            guard dataDescriptor >= 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            dataIdentity = try Self.identity(dataDescriptor)
            generationsDescriptor = Darwin.openat(dataDescriptor,
                "generations", O_RDONLY | O_DIRECTORY | O_NOFOLLOW | O_CLOEXEC)
            guard generationsDescriptor >= 0 else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            generationsIdentity = try Self.identity(generationsDescriptor)
            try requireHeldRoots()
            let (current, _) = try io.control(parent: dataDescriptor,
                name: "current.json")
            let (retired, _) = try io.control(parent: dataDescriptor,
                name: "retired.json")
            guard case .v3(let pointer, _) = try CurrentPointerCodecV1.decode(current),
                  pointer.generationID == sourceGenerationID.uuidString.lowercased(),
                  let retiredValue = try? JSONDecoder().decode(
                    RetiredPointerV1.self, from: retired),
                  try StoreMigrationCanonicalJSONV1.encode(retiredValue) == retired,
                  !retiredValue.generationIDs.contains(
                    sourceGenerationID.uuidString.lowercased()) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
            var sourceFacts: [String: RestoreSourceTreeNodeFactV1] = [:]
            let tree = try io.postRetiredTree(parent: generationsDescriptor,
                name: sourceGenerationID.uuidString.lowercased(),
                observeNode: { path, kind, fields, entries, digest in
                    sourceFacts[path] = RestoreSourceTreeNodeFactV1(
                        kind: kind, fields: fields.components(separatedBy: "|"),
                        entries: entries, digest: digest)
                })
            try requireHeldRoots()
            try io.requireSettled()
            originalCurrent = current
            originalRetired = retired
            sourceTreeDigest = tree
            originalSourceTreeFacts = sourceFacts
            state = .captured
        } catch {
            state = .uncertain
            throw error
        }
    }

    func requireSourceUnchanged(
        stage: RestoreSourceTreeProbeStageV1 = .other,
        allowPostAliasSHMCtime: Bool = false
    ) throws {
        guard state == .captured || state == .closing,
              let sourceTreeDigest,
              originalCurrent != nil, originalRetired != nil else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try requireHeldRoots()
        var currentFacts: [String: RestoreSourceTreeNodeFactV1] = [:]
        let currentDigest = try io.postRetiredTree(parent: generationsDescriptor,
            name: sourceGenerationID.uuidString.lowercased(),
            observeNode: { path, kind, fields, entries, digest in
                currentFacts[path] = RestoreSourceTreeNodeFactV1(
                    kind: kind, fields: fields.components(separatedBy: "|"),
                    entries: entries, digest: digest)
            })
#if DEBUG
        emitSHMCheckpoint(currentFacts, stage: stage,
            treeEqual: currentDigest == sourceTreeDigest)
#endif
        if currentDigest != sourceTreeDigest {
            guard allowPostAliasSHMCtime,
                  (stage == .targetPhysical || stage == .readerClose),
                  hasDrainedOriginalAliases,
                  acceptOnlyPostAliasSHMCtime(currentFacts) else {
#if DEBUG
                emitSourceTreeDifference(currentFacts)
#endif
                throw StoreGenerationFailure.dataPointerInvalid
            }
#if DEBUG
            FileHandle.standardError.write(Data(
                "V23_RESTORE_SHM_POST_ALIAS_V1 result=exact-ctime-projection\n".utf8))
#endif
        }
        try io.requireSettled()
        try requireHeldRoots()
    }

    /// SwiftData can update only the SHM change time while its last original
    /// aliases drain. The initial full-tree/target proof must already have
    /// succeeded. This comparison preserves every path, name, inode, mode,
    /// link, size, mtime and content digest, including the SHM file itself.
    /// A successful first projection freezes the observed ctime for all
    /// later pre-close reproofs; it is never a new baseline for other facts.
    private func acceptOnlyPostAliasSHMCtime(
        _ current: [String: RestoreSourceTreeNodeFactV1]
    ) -> Bool {
        guard preAliasTargetPointer != nil,
              preAliasTargetGenerationID != nil,
              let original = originalSourceTreeFacts,
              Set(original.keys) == Set(current.keys),
              let oldSHM = original["model.sqlite-shm"],
              let newSHM = current["model.sqlite-shm"],
              oldSHM.kind == "file", newSHM.kind == "file",
              oldSHM.fields.count == 9, newSHM.fields.count == 9,
              oldSHM.digest != nil, oldSHM.digest == newSHM.digest else {
            return false
        }
        for path in original.keys {
            guard let old = original[path], let now = current[path],
                  old.kind == now.kind, old.entries == now.entries,
                  old.digest == now.digest,
                  old.fields.count == now.fields.count else {
                return false
            }
            for index in old.fields.indices {
                if path == "model.sqlite-shm" && (index == 7 || index == 8) {
                    continue
                }
                guard old.fields[index] == now.fields[index] else { return false }
            }
        }
        let observed = (seconds: newSHM.fields[7],
                        nanoseconds: newSHM.fields[8])
        if let frozen = postAliasSHMCtime {
            return frozen.seconds == observed.seconds &&
                frozen.nanoseconds == observed.nanoseconds
        }
        postAliasSHMCtime = observed
        return true
    }

#if DEBUG
    private func emitSHMCheckpoint(
        _ current: [String: RestoreSourceTreeNodeFactV1],
        stage: RestoreSourceTreeProbeStageV1,
        treeEqual: Bool
    ) {
        let old = originalSourceTreeFacts?["model.sqlite-shm"]
        let now = current["model.sqlite-shm"]
        let presence: String
        if old == nil && now == nil { presence = "absent" }
        else if old == nil { presence = "added" }
        else if now == nil { presence = "removed" }
        else { presence = "present" }
        func comparison(_ index: Int) -> String {
            guard let old, let now,
                  old.fields.indices.contains(index),
                  now.fields.indices.contains(index) else { return "unavailable" }
            return old.fields[index] == now.fields[index] ? "same" : "changed"
        }
        let content: String
        if let old, let now, let oldDigest = old.digest,
           let nowDigest = now.digest {
            content = oldDigest == nowDigest ? "same" : "changed"
        } else {
            content = "unavailable"
        }
        let tree = treeEqual ? "same" : "changed"
        FileHandle.standardError.write(Data(
            "V23_RESTORE_SHM_CHECKPOINT_V1 stage=\(stage.label) tree=\(tree) presence=\(presence) device=\(comparison(0)) inode=\(comparison(1)) mode=\(comparison(2)) nlink=\(comparison(3)) size=\(comparison(4)) mtimeSeconds=\(comparison(5)) mtimeNanoseconds=\(comparison(6)) ctimeSeconds=\(comparison(7)) ctimeNanoseconds=\(comparison(8)) content=\(content)\n".utf8))
    }

    private func emitSourceTreeDifference(
        _ current: [String: RestoreSourceTreeNodeFactV1]
    ) {
        guard let original = originalSourceTreeFacts else {
            FileHandle.standardError.write(Data(
                "V23_RESTORE_SOURCE_TREE_DIFFERENCE_V1 category=all first=unavailable\n".utf8))
            return
        }
        func category(_ path: String) -> String {
            if path.isEmpty { return "root" }
            let leaf = path.split(separator: "/").last.map(String.init) ?? ""
            switch leaf {
            case "model.sqlite": return "sqlite"
            case "model.sqlite-wal": return "wal"
            case "model.sqlite-shm": return "shm"
            default: return "other"
            }
        }
        let labels = ["device", "inode", "mode", "nlink", "size",
                      "mtime-seconds", "mtime-nanoseconds", "ctime-seconds",
                      "ctime-nanoseconds"]
        for group in ["root", "sqlite", "wal", "shm", "other"] {
            let oldPaths = Set(original.keys.filter { category($0) == group })
            let newPaths = Set(current.keys.filter { category($0) == group })
            var first = "equal"
            if oldPaths != newPaths {
                first = "membership"
            } else {
                for path in oldPaths.sorted() {
                    guard let old = original[path], let now = current[path] else {
                        first = "membership"
                        break
                    }
                    if old.kind != now.kind { first = "kind"; break }
                    if old.entries != now.entries { first = "entries"; break }
                    if old.fields.count != now.fields.count {
                        first = "field-count"
                        break
                    }
                    if let index = old.fields.indices.first(where: {
                        old.fields[$0] != now.fields[$0]
                    }) {
                        first = index < labels.count ? labels[index] : "field-other"
                        break
                    }
                    if old.digest != now.digest { first = "bytes"; break }
                }
            }
            FileHandle.standardError.write(Data(
                "V23_RESTORE_SOURCE_TREE_DIFFERENCE_V1 category=\(group) first=\(first)\n".utf8))
        }
    }
#endif

    func requireOriginalPointerAttestation(_ canonicalPointer: Data) throws {
        guard state == .captured,
              originalCurrent == canonicalPointer,
              case .v3(let pointer, _) = try CurrentPointerCodecV1.decode(
                  canonicalPointer),
              try pointer.canonicalData() == canonicalPointer,
              pointer.generationID == sourceGenerationID.uuidString.lowercased() else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try requireSourceUnchanged(stage: .pointerAttestation)
    }

    /// The maintenance route has no published Coordinator. Its source is the
    /// exact original reader and context captured before Restore effects, not
    /// merely any later maintenance session in the Router slot.
    func requireObservedMaintenanceSource(_ session: StoreGenerationSession,
        context: ModelContext, openingFactory: StoreGenerationFactory) throws {
        guard state == .captured,
              observedCoordinator == nil,
              observedSession === session,
              observedContext === context,
              observedContainer === context.container,
              session.modelContext === context,
              session.generationID == sourceGenerationID,
              try session.validatedOpeningFactoryForWriter()
                .sharesRegistryProvider(with: openingFactory),
              try session.retainedReaderForOriginalRestoreTransition(
                  factory: openingFactory) === reader else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        try registry.validateActive(reader.token, requiredRole: .reader)
        try requireSourceUnchanged(stage: .maintenanceSource)
    }

    /// A target session alone is not publication proof. Observe the actual
    /// current control through A's held data root without a reparative load,
    /// then bind its typed identity to B's already-opened session/reader.
    func requireTargetPublished(_ target: StoreGenerationSession,
        openingFactory: StoreGenerationFactory,
        intendedCanonicalPointer: Data) throws {
#if DEBUG
        var stage = "target-physical"
#endif
        do {
            try requireTargetPhysicalPublished(target,
                openingFactory: openingFactory,
                intendedCanonicalPointer: intendedCanonicalPointer)
        // A matching target URL/epoch alone does not bind B's provider to
        // A's held source root. The actual A reader and B Registry must name
        // the same physical root/Operations/lease/lock controls before A's
        // writer can close. This also runs again on the pending same-ID retry.
            #if DEBUG
            stage = "target-registry"
            #endif
            let targetRegistry = try openingFactory.makeGenerationLeaseRegistry()
            #if DEBUG
            stage = "source-reader-identity"
            #endif
            try reader.requireLiveTemporalIdentity(mutationRegistry: targetRegistry)
            #if DEBUG
            stage = "source-reader-active"
            #endif
            try registry.validateActive(reader.token, requiredRole: .reader)
            #if DEBUG
            stage = "target-reader-owner"
            #endif
            let targetReader = try target.retainedReaderForOriginalRestoreTransition(
                factory: openingFactory)
            #if DEBUG
            stage = "target-reader-registry"
            #endif
            try targetReader.requireExactRegistry(targetRegistry)
            #if DEBUG
            stage = "target-reader-active"
            #endif
            try targetRegistry.validateActive(targetReader.token, requiredRole: .reader)
            if !hasDrainedOriginalAliases {
                guard preAliasTargetPointer == nil ||
                        (preAliasTargetPointer == intendedCanonicalPointer &&
                         preAliasTargetGenerationID == target.generationID) else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                preAliasTargetPointer = intendedCanonicalPointer
                preAliasTargetGenerationID = target.generationID
            }
        } catch {
#if DEBUG
            FileHandle.standardError.write(Data(
                "V23_RESTORE_TARGET_PROOF_V1 first=\(stage) errorType=\(String(reflecting: type(of: error)))\n".utf8))
#endif
            throw error
        }
    }

    private func requireTargetPhysicalPublished(_ target: StoreGenerationSession,
        openingFactory: StoreGenerationFactory,
        intendedCanonicalPointer: Data,
        probeStage: RestoreSourceTreeProbeStageV1 = .targetPhysical) throws {
#if DEBUG
        var stage = "target-association"
#endif
        do {
        guard state == .captured || state == .closing,
              target.generationID != sourceGenerationID,
              let targetEpoch = target.generationEpoch,
              targetEpoch.generationID == target.generationID,
              openingFactory.restoreApplicationSupportURL.standardizedFileURL
                == applicationSupportURL.standardizedFileURL,
              target.generationRootURL.standardizedFileURL
                == openingFactory.installedGenerationURL(
                    id: target.generationID).standardizedFileURL else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
#if DEBUG
        stage = "intended-pointer"
#endif
        guard case .v3(let intended, _) = try CurrentPointerCodecV1.decode(
                intendedCanonicalPointer),
              try intended.canonicalData() == intendedCanonicalPointer,
              intended.generationID == target.generationID.uuidString.lowercased(),
              intended.generationManifestSHA256
                == targetEpoch.generationManifestSHA256,
              intended.workspaceID
                == target.workspaceID.rawValue.uuidString.lowercased(),
              intended.replicaID
                == target.replicaID.rawValue.uuidString.lowercased(),
              intended.storeSchemaVersion
                == target.storeSchemaRelease.versionIdentifier.major else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
#if DEBUG
        stage = "held-roots-before-current"
#endif
        try requireHeldRoots()
#if DEBUG
        stage = "current-control"
#endif
        let (current, _) = try io.control(parent: dataDescriptor,
            name: "current.json")
#if DEBUG
        stage = "current-pointer-equality"
#endif
        guard case .v3(let pointer, _) = try CurrentPointerCodecV1.decode(current),
              current == intendedCanonicalPointer,
              pointer == intended else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        // Read the exact target manifest through A's retained support root.
        // These transient no-follow descriptors are checked-close owned by io.
#if DEBUG
        stage = "target-manifest"
#endif
        let manifestName = "manifest-" + target.generationID.uuidString.lowercased()
            + ".json"
        try io.withOpen(parent: supportDescriptor, name: "FieldEvidenceOperations",
            flags: O_RDONLY | O_DIRECTORY) { operations in
            try io.withOpen(parent: operations, name: "schema-migration",
                flags: O_RDONLY | O_DIRECTORY) { migration in
                let (bytes, _) = try io.control(parent: migration,
                    name: manifestName)
                let manifest = try StoreGenerationManifestV1.decodeCanonical(
                    from: bytes)
                guard StoreMigrationCanonicalJSONV1.sha256(bytes)
                        == targetEpoch.generationManifestSHA256,
                      manifest.generationID == target.generationID,
                      manifest.predecessorGenerationID == sourceGenerationID,
                      manifest.storeSchemaRelease == target.storeSchemaRelease else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
        }
#if DEBUG
        stage = "retired-control"
#endif
        let (retired, _) = try io.control(parent: dataDescriptor,
            name: "retired.json")
#if DEBUG
        stage = "retired-canonical"
#endif
        guard let originalRetired,
              let prior = try? JSONDecoder().decode(
                RetiredPointerV1.self, from: originalRetired),
              let published = try? JSONDecoder().decode(
                RetiredPointerV1.self, from: retired),
              try StoreMigrationCanonicalJSONV1.encode(published) == retired,
              published.schemaVersion == prior.schemaVersion else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        let expectedRetired = Array(Set(prior.generationIDs + [
            sourceGenerationID.uuidString.lowercased()])).sorted()
#if DEBUG
        stage = "retired-transition"
#endif
        guard published.generationIDs == expectedRetired,
              !published.generationIDs.contains(
                target.generationID.uuidString.lowercased()) else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
#if DEBUG
        stage = "source-tree"
#endif
        let postAliasCtimeEligible =
            preAliasTargetPointer == intendedCanonicalPointer &&
            preAliasTargetGenerationID == target.generationID &&
            hasDrainedOriginalAliases
        try requireSourceUnchanged(stage: probeStage,
            allowPostAliasSHMCtime: postAliasCtimeEligible)
        } catch {
#if DEBUG
            FileHandle.standardError.write(Data(
                "V23_RESTORE_PHYSICAL_PROOF_V1 first=\(stage) errorType=\(String(reflecting: type(of: error)))\n".utf8))
#endif
            throw error
        }
    }

    /// Weak drain is necessary but not sufficient: the exact A reader remains
    /// active until the source tree and full A+B token census pass under G.
    @MainActor
    func closeAfterCheckedAliasDrain(targetRegistry: GenerationLeaseRegistryV1,
        targetReader: GenerationLeaseHandleV1,
        targetWriter: GenerationLeaseHandleV1,
        targetSession: StoreGenerationSession,
        targetFactory: StoreGenerationFactory,
        intendedCanonicalPointer: Data) throws {
        guard state == .captured,
              observedSession == nil, observedContext == nil,
              observedContainer == nil, observedCoordinator == nil else {
#if DEBUG
            FileHandle.standardError.write(Data(
                "V23_RESTORE_SOURCE_CLOSE_V1 first=alias-or-state\n".utf8))
#endif
            throw StoreGenerationFailure.dataPointerInvalid
        }
        state = .closing
#if DEBUG
        var stage = "reader-close"
#endif
        do {
            try reader.closeForOriginalRestoreTransition(
                registry: registry, targetRegistry: targetRegistry,
                targetReader: targetReader, targetWriter: targetWriter,
                reproveSource: { [self] in
                    try requireTargetPhysicalPublished(targetSession,
                        openingFactory: targetFactory,
                        intendedCanonicalPointer: intendedCanonicalPointer,
                        probeStage: .readerClose)
                })
#if DEBUG
            stage = "registry-close"
#endif
            try registry.closeOriginalRestoreSourceOwner(
                sourceReader: reader, targetRegistry: targetRegistry,
                targetReader: targetReader, targetWriter: targetWriter)
#if DEBUG
            stage = "transient-drain"
#endif
            try io.requireSettled()
#if DEBUG
            stage = "base-descriptor-close"
#endif
            for descriptor in [generationsDescriptor, dataDescriptor, supportDescriptor] {
                guard Darwin.close(descriptor) == 0 else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
            }
            generationsDescriptor = -1
            dataDescriptor = -1
            supportDescriptor = -1
            state = .closed
        } catch {
#if DEBUG
            FileHandle.standardError.write(Data(
                "V23_RESTORE_SOURCE_CLOSE_V1 first=\(stage) errorType=\(String(reflecting: type(of: error)))\n".utf8))
#endif
            state = .uncertain
            throw error
        }
    }

    var hasDrainedOriginalAliases: Bool {
        observedSession == nil && observedContext == nil &&
        observedContainer == nil && observedCoordinator == nil
    }

#if DEBUG
    /// Fixed presence categories only. This does not acquire, release, or
    /// extend any original SwiftData alias used by the authoritative drain.
    func originalAliasPresenceForTesting() -> (
        session: Bool, context: Bool, container: Bool, coordinator: Bool
    ) {
        (observedSession != nil, observedContext != nil,
         observedContainer != nil, observedCoordinator != nil)
    }
#endif

    var isCheckedClosed: Bool {
        if case .closed = state { return true }
        return false
    }
}

struct StoreApplicationSupportIdentity: Equatable {
    let device: dev_t
    let inode: ino_t
}

enum StoreGenerationFailure: Error, Equatable {
    case dataPointerInvalid
    case dataGenerationMissing
}

#if DEBUG
private enum EraseFileSnapshotStageV1: String, Codable {
    case beforeTargetOpen
    case beforeManifestOpen
    case afterManifestSemantic
}

private enum EraseManifestObservationV1: String, Codable {
    case notLoaded
    case present
    case missing
    case loadFailed
}

private struct EraseFileSnapshotErrorV1: Codable {
    let swiftType: String
    let domain: String
    let code: Int

    init(_ error: Error) {
        let value = error as NSError
        swiftType = String(reflecting: type(of: error))
        domain = value.domain
        code = value.code
    }
}

private struct EraseFileSnapshotVectorV1: Codable {
    let totalCount: Int
    let prefixFiles: [StoreGenerationFileDigestV1]
    let truncated: Bool
    let canonicalSHA256: String

    init(_ files: [StoreGenerationFileDigestV1]) throws {
        totalCount = files.count
        prefixFiles = Array(files.prefix(32))
        truncated = files.count > 32
        canonicalSHA256 = try StoreMigrationCanonicalJSONV1.digest(files)
    }
}

private struct EraseFileSnapshotRecordV1: Codable {
    let generationID: UUID
    let stage: EraseFileSnapshotStageV1
    let manifestObservation: EraseManifestObservationV1
    let expectedFiles: EraseFileSnapshotVectorV1?
    let observedFiles: EraseFileSnapshotVectorV1?
    let filesEqual: Bool?
    let manifestLoadError: EraseFileSnapshotErrorV1?
    let filesAcquisitionError: EraseFileSnapshotErrorV1?
}
#endif

enum StorePointerSchemaRegistry {
    static let legacyCurrentVersion = 1
    static let manifestCurrentVersion = 2
    static let identityCurrentVersion = 3
    static let retiredVersion = 1

    static func requireCurrent(_ version: Int) throws {
        guard version == legacyCurrentVersion
                || version == manifestCurrentVersion
                || version == identityCurrentVersion else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    static func requireRetired(_ version: Int) throws {
        guard version == retiredVersion else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }
}

private extension StoreGenerationFactory {
    @MainActor
    private func beginMigration(
        sourcePointer: CurrentGenerationPointerV3,
        sourcePointerData: Data,
        retired: RetiredPointerV1,
        dataRootURL: URL,
        store: StoreMigrationJournalStoreV1,
        processID: UUID
    ) throws -> StoreGenerationSession {
        try sourcePointer.validate()
        guard (2..<PersistentSchemaReleaseRegistryV1.activeVersionIdentifier.major)
                .contains(sourcePointer.storeSchemaVersion),
              let sourceID = canonicalUUID(from: sourcePointer.generationID),
              !retired.generationIDs.contains(sourcePointer.generationID) else {
            throw StoreMigrationFailure.maintenanceRequired(.invalidPointer)
        }
        let sourceManifest = try store.loadManifest(
            targetGenerationID: sourceID,
            expectedDigest: sourcePointer.generationManifestSHA256
        )
        guard let sourceRelease = PersistentSchemaReleaseV1(
            rawValue: "V\(sourcePointer.storeSchemaVersion)"
        ), let targetRelease = PersistentSchemaReleaseV1(
            rawValue: "V\(sourcePointer.storeSchemaVersion + 1)"
        ), targetRelease.predecessorVersionIdentifier == sourceRelease.versionIdentifier else {
            throw StoreMigrationFailure.maintenanceRequired(.invalidPointer)
        }
        guard sourceManifest.schemaVersion == 1, sourceManifest.storeSchemaRelease == sourceRelease,
              sourceManifest.semanticSHA256 != nil else {
            throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
        }
        let identities = migrationIdentitySource ?? .live
        let targetID = identities.makeGenerationID()
        guard sourceManifest.migrationID != targetID,
              sourceID != targetID else {
            throw StoreMigrationFailure.invalidIdentity
        }
        let authority = try makeRestoreGenerationAuthority()
        try authority.requireNoRestoreJournal()
        try authority.requireNoEraseAuthority()
        let snapshot = try authority.snapshotInstalledGeneration(id: sourceID)
        guard snapshot.files == sourceManifest.files,
              snapshot.frozenIdentityDigest == sourceManifest.frozenIdentityDigest else {
            throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
        }
        let pointerDigest = StoreMigrationCanonicalJSONV1.sha256(sourcePointerData)
        let prepared = try StoreMigrationJournalV1(
            migrationID: sourceManifest.migrationID,
            sourceGenerationID: sourceID,
            targetGenerationID: targetID,
            sourceRelease: sourceRelease,
            targetRelease: targetRelease,
            sourcePointerDigest: pointerDigest,
            sourceTreeDigest: snapshot.sourceTreeDigest,
            sourceManifestDigest: sourcePointer.generationManifestSHA256,
            frozenIdentityDigest: snapshot.frozenIdentityDigest,
            expectedPointerDigest: pointerDigest,
            originatingProcessID: processID,
            phase: .prepared,
            targetWritePossible: false,
            pointerPublicationAttempted: false
        )
        try reachMigrationBoundary(.beforePreparedJournalWrite)
        try store.createPreparedMigration(journal: prepared, sourceManifest: sourceManifest)
        try reachMigrationBoundary(.afterPreparedJournalWrite)
        return try resumeMigration(
            prepared,
            dataRootURL: dataRootURL,
            store: store,
            processID: processID
        )
    }

    @MainActor
    private func beginMigration(
        sourcePointer: CurrentPointerV1,
        sourcePointerData: Data,
        retired: RetiredPointerV1,
        dataRootURL: URL,
        store: StoreMigrationJournalStoreV1,
        processID: UUID
    ) throws -> StoreGenerationSession {
        guard sourcePointer.schemaVersion
                == StorePointerSchemaRegistry.legacyCurrentVersion,
              let sourceID = canonicalUUID(from: sourcePointer.generationID),
              !retired.generationIDs.contains(sourcePointer.generationID) else {
            throw StoreMigrationFailure.maintenanceRequired(.invalidPointer)
        }
        let identities = migrationIdentitySource ?? .live
        let migrationID = identities.makeMigrationID()
        let targetID = identities.makeGenerationID()
        guard migrationID != sourceID,
              migrationID != targetID,
              sourceID != targetID else {
            throw StoreMigrationFailure.invalidIdentity
        }

        do {
            let authority = try makeRestoreGenerationAuthority()
            try authority.requireNoRestoreJournal()
            try authority.requireNoEraseAuthority()
            let sourceSnapshot = try authority.snapshotInstalledGeneration(id: sourceID)
            let sourceManifest = try StoreGenerationManifestV1(
                generationID: sourceID,
                predecessorGenerationID: syntheticPredecessor(excluding: sourceID),
                migrationID: migrationID,
                storeSchemaRelease: .v1,
                semanticSHA256: nil,
                frozenIdentityDigest: sourceSnapshot.frozenIdentityDigest,
                files: sourceSnapshot.files
            )
            let sourceManifestDigest = try sourceManifest.canonicalSHA256()
            let pointerDigest = StoreMigrationCanonicalJSONV1.sha256(sourcePointerData)
            let prepared = try StoreMigrationJournalV1(
                migrationID: migrationID,
                sourceGenerationID: sourceID,
                targetGenerationID: targetID,
                sourceRelease: .v1,
                targetRelease: .v2,
                sourcePointerDigest: pointerDigest,
                sourceTreeDigest: sourceSnapshot.sourceTreeDigest,
                sourceManifestDigest: sourceManifestDigest,
                frozenIdentityDigest: sourceSnapshot.frozenIdentityDigest,
                expectedPointerDigest: pointerDigest,
                originatingProcessID: processID,
                phase: .prepared,
                targetWritePossible: false,
                pointerPublicationAttempted: false
            )
            try reachMigrationBoundary(.beforePreparedJournalWrite)
            try store.createPreparedMigration(
                journal: prepared,
                sourceManifest: sourceManifest
            )
            try reachMigrationBoundary(.afterPreparedJournalWrite)
            return try resumeMigration(
                prepared,
                dataRootURL: dataRootURL,
                store: store,
                processID: processID
            )
        } catch let failure as StoreMigrationFailure {
            throw failure
        } catch {
            if let reason = migrationMaintenanceReason(for: error) {
                throw StoreMigrationFailure.maintenanceRequired(reason)
            }
            throw error
        }
    }

    @MainActor
    private func resumeMigration(
        _ persisted: StoreMigrationJournalV1,
        dataRootURL: URL,
        store: StoreMigrationJournalStoreV1,
        processID: UUID,
        continueAdjacentMigration: Bool = true
    ) throws -> StoreGenerationSession {
        do {
            return try resumeMigrationForward(
                persisted,
                dataRootURL: dataRootURL,
                store: store,
                processID: processID,
                continueAdjacentMigration: continueAdjacentMigration
            )
        } catch let failure as StoreMigrationFailure {
            let effectivePhase = (try? store.loadJournal())?.phase
                ?? persisted.phase
            switch failure {
            case .injectedFault, .maintenanceRequired:
                throw failure
            default:
                if effectivePhase.isAtLeast(.v2WriteAuthorized) {
                    throw StoreMigrationFailure.maintenanceRequired(
                        .forwardFixRequired
                    )
                }
                throw failure
            }
        } catch let failure as ProtectedFilePolicyError
            where failure == .protectedDataUnavailable {
            throw StoreMigrationFailure.maintenanceRequired(
                .protectedDataUnavailable
            )
        } catch {
            let effectivePhase = (try? store.loadJournal())?.phase
                ?? persisted.phase
            if let reason = migrationMaintenanceReason(for: error) {
                throw StoreMigrationFailure.maintenanceRequired(reason)
            }
            if effectivePhase.isAtLeast(.v2WriteAuthorized) {
                throw StoreMigrationFailure.maintenanceRequired(.forwardFixRequired)
            }
            throw error
        }
    }

    private func migrationMaintenanceReason(
        for error: Error
    ) -> StoreMigrationMaintenanceReasonV1? {
        var current = error as NSError
        for _ in 0..<8 {
            if ProtectedFilePolicyV1.isProtectedDataUnavailable(current) {
                return .protectedDataUnavailable
            }
            if current.domain == NSPOSIXErrorDomain,
               current.code == ENOSPC {
                return .insufficientStorage
            }
            if current.domain == NSCocoaErrorDomain,
               current.code == NSFileWriteOutOfSpaceError {
                return .insufficientStorage
            }
            guard let underlying = current.userInfo[NSUnderlyingErrorKey]
                    as? NSError,
                  underlying !== current else {
                break
            }
            current = underlying
        }
        return nil
    }

    @MainActor
    private func resumeMigrationForward(
        _ persisted: StoreMigrationJournalV1,
        dataRootURL: URL,
        store: StoreMigrationJournalStoreV1,
        processID: UUID,
        continueAdjacentMigration: Bool = true
    ) throws -> StoreGenerationSession {
        var journal = persisted
        try journal.validate()
        let authority = try makeRestoreGenerationAuthority()
        try authority.requireNoRestoreJournal()
        try authority.requireNoEraseAuthority()

        while true {
            try requireMigrationPointerState(journal)
            switch journal.phase {
            case .prepared:
                let sourceManifest = try requireSourceManifest(
                    journal,
                    store: store
                )
                let sourceSnapshot = try authority.snapshotInstalledGeneration(
                    id: journal.sourceGenerationID
                )
                guard sourceSnapshot.sourceTreeDigest == journal.sourceTreeDigest,
                      sourceSnapshot.frozenIdentityDigest == journal.frozenIdentityDigest,
                      sourceSnapshot.files == sourceManifest.files else {
                    throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
                }
                let presence = try authority.presence(id: journal.targetGenerationID)
                guard !presence.installed else {
                    throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
                }
                if presence.staging {
                    try authority.removeStagingGeneration(id: journal.targetGenerationID)
                }
                try reachMigrationBoundary(.beforeSourceClone)
                try authority.createStagingGeneration(id: journal.targetGenerationID)
                let cloned = try authority.cloneInstalledGeneration(
                    sourceID: journal.sourceGenerationID,
                    toStagingGeneration: journal.targetGenerationID
                )
                guard cloned.sourceTreeDigest == journal.sourceTreeDigest,
                      cloned.frozenIdentityDigest == journal.frozenIdentityDigest,
                      cloned.files == sourceManifest.files else {
                    throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
                }
#if DEBUG
                let sourceSemantic = try adjacentDiagnosticSemanticExport(
                    at: restoreStagingGenerationURL(id: journal.targetGenerationID),
                    release: journal.sourceRelease, phase: "prepared.semantic-open",
                    expectedFiles: sourceManifest.files, expectedTreeDigest: journal.sourceTreeDigest,
                    operationID: journal.migrationID)
#else
                let sourceSemantic = try privateSemanticExport(
                    at: restoreStagingGenerationURL(
                        id: journal.targetGenerationID
                    ).appendingPathComponent(Self.modelStoreName),
                    release: journal.sourceRelease,
                    markerMigrationID: nil, operationID: journal.migrationID
                )
#endif
                if journal.sourceRelease != .v1,
                   sourceManifest.semanticSHA256
                    != StoreMigrationCanonicalJSONV1.sha256(sourceSemantic) {
                    throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
                }
                let next = try migrationJournal(
                    journal,
                    phase: .sourceCloned,
                    sourceSemanticDigest:
                        StoreMigrationCanonicalJSONV1.sha256(sourceSemantic)
                )
                try store.replaceJournal(expected: journal, with: next)
                journal = next
                try reachMigrationBoundary(.afterSourceClone)

            case .sourceCloned:
                let targetRoot = restoreStagingGenerationURL(
                    id: journal.targetGenerationID
                )
                if processID != journal.originatingProcessID {
                    let recoveredPresence = try authority.presence(
                        id: journal.targetGenerationID
                    )
                    guard !recoveredPresence.installed else {
                        throw StoreMigrationFailure.maintenanceRequired(
                            .targetMismatch
                        )
                    }
                    if recoveredPresence.staging {
                        try authority.removeStagingGeneration(
                            id: journal.targetGenerationID
                        )
                    }
                    try authority.createStagingGeneration(
                        id: journal.targetGenerationID
                    )
                    let recoveredClone = try authority.cloneInstalledGeneration(
                        sourceID: journal.sourceGenerationID,
                        toStagingGeneration: journal.targetGenerationID
                    )
                    guard recoveredClone.sourceTreeDigest
                            == journal.sourceTreeDigest,
                          recoveredClone.frozenIdentityDigest
                            == journal.frozenIdentityDigest else {
                        throw StoreMigrationFailure.maintenanceRequired(
                            .sourceMismatch
                        )
                    }
                }
                guard try authority.presence(id: journal.targetGenerationID).staging,
                      try generationTreeDigest(at: targetRoot)
                        == journal.sourceTreeDigest else {
#if DEBUG
                    print("StoreMigration.adjacent.guard phase=sourceCloned reason=staging-or-tree sameProcess=\(processID == journal.originatingProcessID)")
                    let expectedFiles = try? requireSourceManifest(journal, store: store).files
                    _ = adjacentDiagnosticFiles(at: targetRoot, phase: "sourceCloned.guard",
                        expectedFiles: expectedFiles, expectedTreeDigest: journal.sourceTreeDigest)
#endif
                    throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
                }
#if DEBUG
                let recoveredSourceSemantic = try adjacentDiagnosticSemanticExport(
                    at: targetRoot, release: journal.sourceRelease, phase: "sourceCloned.semantic-open",
                    expectedFiles: nil, expectedTreeDigest: journal.sourceTreeDigest, operationID: journal.migrationID)
#else
                let recoveredSourceSemantic = try privateSemanticExport(
                    at: targetRoot.appendingPathComponent(Self.modelStoreName),
                    release: journal.sourceRelease,
                    markerMigrationID: nil, operationID: journal.migrationID
                )
#endif
                guard StoreMigrationCanonicalJSONV1.sha256(
                    recoveredSourceSemantic
                ) == journal.sourceSemanticDigest else {
#if DEBUG
                    print("StoreMigration.adjacent.guard phase=sourceCloned reason=semantic-digest")
#endif
                    throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
                }
                try reachMigrationBoundary(.beforeV2WriteAuthorization)
                let next = try migrationJournal(
                    journal,
                    phase: .v2WriteAuthorized,
                    targetWritePossible: true
                )
                try store.replaceJournal(expected: journal, with: next)
                journal = next
                try reachMigrationBoundary(.afterV2WriteAuthorization)

            case .v2WriteAuthorized:
                let targetRoot = restoreStagingGenerationURL(
                    id: journal.targetGenerationID
                )
                guard try authority.presence(id: journal.targetGenerationID).staging else {
                    throw StoreMigrationFailure.maintenanceRequired(.targetUnavailable)
                }
                try reachMigrationBoundary(.beforeV2Validation)
                let targetSemantic = try migrateAndValidateClone(
                    at: targetRoot,
                    sourceRelease: journal.sourceRelease,
                    targetRelease: journal.targetRelease,
                    migrationID: journal.migrationID,
                    sourceGenerationID: journal.sourceGenerationID,
                    targetGenerationID: journal.targetGenerationID,
                    expectedSemanticDigest: try requiredSourceSemanticDigest(
                        journal
                    )
                )
                try protectGeneration(
                    at: targetRoot,
                    staging: true,
                    requireModel: true
                )
                let targetManifest = try StoreGenerationManifestV1(
                    generationID: journal.targetGenerationID,
                    predecessorGenerationID: journal.sourceGenerationID,
                    migrationID: journal.migrationID,
                    storeSchemaRelease: journal.targetRelease,
                    semanticSHA256: targetSemantic,
                    frozenIdentityDigest: try frozenIdentityDigest(for: targetRoot),
                    files: try generationFileDigests(at: targetRoot, durable: true)
                )
                let targetManifestDigest = try store.writeManifest(targetManifest)
                let desiredPointerDigest = StoreMigrationCanonicalJSONV1.sha256(
                    try desiredMigrationPointerData(
                        journal: journal,
                        manifestDigest: targetManifestDigest
                    )
                )
                let next = try migrationJournal(
                    journal,
                    phase: .v2Validated,
                    targetManifestDigest: targetManifestDigest,
                    targetSemanticDigest: targetSemantic,
                    desiredPointerDigest: desiredPointerDigest
                )
                try store.replaceJournal(expected: journal, with: next)
                journal = next
                try reachMigrationBoundary(.afterV2Validation)

            case .v2Validated:
                let targetManifest = try requireTargetManifest(
                    journal,
                    store: store
                )
                let presence = try authority.presence(id: journal.targetGenerationID)
                guard presence.staging != presence.installed else {
                    throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
                }
                if presence.staging {
                    try requireTargetGenerationSnapshot(
                        journal,
                        manifest: targetManifest,
                        at: restoreStagingGenerationURL(
                            id: journal.targetGenerationID
                        )
                    )
                    try reachMigrationBoundary(.beforeGenerationInstall)
                    try authority.installStagingGeneration(id: journal.targetGenerationID)
                }
                try authority.requireInstalledGeneration(id: journal.targetGenerationID)
                try requireTargetGenerationSnapshot(
                    journal,
                    manifest: targetManifest,
                    at: installedGenerationURL(id: journal.targetGenerationID)
                )
                let next = try migrationJournal(
                    journal,
                    phase: .generationInstalled
                )
                try store.replaceJournal(expected: journal, with: next)
                journal = next
                try reachMigrationBoundary(.afterGenerationInstall)

            case .generationInstalled:
                try authority.requireInstalledGeneration(id: journal.targetGenerationID)
                try requireTargetGenerationSnapshot(
                    journal,
                    manifest: try requireTargetManifest(journal, store: store),
                    at: installedGenerationURL(id: journal.targetGenerationID)
                )
                if !journal.pointerPublicationAttempted {
                    let next = try migrationJournal(
                        journal,
                        phase: .generationInstalled,
                        publicationProcessID: processID,
                        pointerPublicationAttempted: true
                    )
                    try store.replaceJournal(expected: journal, with: next)
                    journal = next
                    continue
                }
                try reachMigrationBoundary(.beforePointerPublication)
                try publishMigrationPointerForwardOnly(journal, store: store)
                let next = try migrationJournal(
                    journal,
                    phase: .pointerPublished
                )
                try store.replaceJournal(expected: journal, with: next)
                journal = next
                try reachMigrationBoundary(.afterPointerPublication)

            case .pointerPublished:
                try reachMigrationBoundary(.beforeFirstLaunchValidation)
                let session = try openPublishedMigrationTarget(
                    journal,
                    dataRootURL: dataRootURL,
                    store: store
                )
                let next = try migrationJournal(
                    journal,
                    phase: .firstLaunchValidated,
                    firstValidationProcessID: processID
                )
                try store.replaceJournal(expected: journal, with: next)
                try reachMigrationBoundary(.afterFirstLaunchValidation)
                return session

            case .firstLaunchValidated:
                guard processID != journal.publicationProcessID,
                      processID != journal.originatingProcessID,
                      processID != journal.firstValidationProcessID else {
                    return try openPublishedMigrationTarget(
                        journal,
                        dataRootURL: dataRootURL,
                        store: store
                    )
                }
                try reachMigrationBoundary(.beforeSecondLaunchValidation)
                let session = try openPublishedMigrationTarget(
                    journal,
                    dataRootURL: dataRootURL,
                    store: store
                )
                let next = try migrationJournal(
                    journal,
                    phase: .secondLaunchValidated,
                    secondValidationProcessID: processID
                )
                try store.replaceJournal(expected: journal, with: next)
                journal = next
                try reachMigrationBoundary(.afterSecondLaunchValidation)
                try finishMigration(
                    journal,
                    authority: authority,
                    store: store
                )
                if !continueAdjacentMigration { return session }
                return try continueIntoActiveReleaseIfNeeded(
                    after: journal,
                    validatedSession: session,
                    authority: authority,
                    dataRootURL: dataRootURL,
                    store: store,
                    processID: processID
                )

            case .secondLaunchValidated:
                let session = try openPublishedMigrationTarget(
                    journal,
                    dataRootURL: dataRootURL,
                    store: store
                )
                try finishMigration(
                    journal,
                    authority: authority,
                    store: store
                )
                if !continueAdjacentMigration { return session }
                return try continueIntoActiveReleaseIfNeeded(
                    after: journal,
                    validatedSession: session,
                    authority: authority,
                    dataRootURL: dataRootURL,
                    store: store,
                    processID: processID
                )
            }
        }
    }

    /// Closes one accepted adjacent migration and starts the next without
    /// recursively re-entering startup. A V2 session must never escape once
    /// V3 is the active release because ledger-aware callers can only use a
    /// V3 ModelContext.
    @MainActor
    private func continueIntoActiveReleaseIfNeeded(
        after completed: StoreMigrationJournalV1,
        validatedSession: StoreGenerationSession,
        authority: StoreRestoreGenerationAuthority,
        dataRootURL: URL,
        store: StoreMigrationJournalStoreV1,
        processID: UUID
    ) throws -> StoreGenerationSession {
        guard completed.targetRelease != PersistentSchemaReleaseRegistryV1.activeRelease else {
            return validatedSession
        }
              guard [.v2, .v3, .v4, .v5, .v6, .v7, .v8, .v9, .v10, .v11, .v12, .v13, .v14, .v15, .v16, .v17, .v18, .v19, .v20, .v21, .v22, .v23, .v24, .v25, .v26,.v27,.v28,.v29,.v30,.v31,.v32,.v33,.v34,.v35,.v36,.v37,.v38,.v39,.v40,.v41,.v42,.v43,.v44,.v45,.v46,.v47,.v48,.v49,.v50,.v51,.v52,.v53].contains(completed.targetRelease),
              PersistentSchemaReleaseRegistryV1.activeRelease == .v53 else {
            throw StoreMigrationFailure.maintenanceRequired(.futureVersion)
        }
        let current = try decodeCurrentPointer(
            at: dataRootURL.appendingPathComponent(Self.currentPointerName)
        )
        let completedVersion: Int
        switch completed.targetRelease {
        case .v2: completedVersion = 2
        case .v3: completedVersion = 3
        case .v4: completedVersion = 4
        case .v5: completedVersion = 5
        case .v6: completedVersion = 6
        case .v7: completedVersion = 7
        case .v8: completedVersion = 8
        case .v9: completedVersion = 9
        case .v10: completedVersion = 10
        case .v11: completedVersion = 11
        case .v12: completedVersion = 12
        case .v13: completedVersion = 13
        case .v14: completedVersion = 14
        case .v15: completedVersion = 15
        case .v16: completedVersion = 16
        case .v17: completedVersion = 17
        case .v18: completedVersion = 18
        case .v19: completedVersion = 19
        case .v20: completedVersion = 20
        case .v21: completedVersion = 21
        case .v22: completedVersion = 22
        case .v23: completedVersion = 23
        case .v24: completedVersion = 24
        case .v25: completedVersion = 25
        case .v26: completedVersion = 26
        case .v27: completedVersion = 27
        case .v28: completedVersion = 28
        case .v29: completedVersion = 29
        case .v30: completedVersion = 30
        case .v31: completedVersion = 31
        case .v32: completedVersion = 32
        case .v33: completedVersion = 33
        case .v34: completedVersion = 34
        case .v35: completedVersion = 35
        case .v36: completedVersion = 36
        case .v37: completedVersion = 37
        case .v38: completedVersion = 38
        case .v39: completedVersion = 39
        case .v40: completedVersion = 40
        case .v41: completedVersion = 41
        case .v42: completedVersion = 42
        case .v43: completedVersion = 43
        case .v44: completedVersion = 44
        case .v45: completedVersion = 45
        case .v46: completedVersion = 46
        case .v47: completedVersion = 47
        case .v48: completedVersion = 48
        case .v49: completedVersion = 49
        case .v50: completedVersion = 50
        case .v51: completedVersion = 51
        case .v52: completedVersion = 52
        case .v53: completedVersion = 53
        default: throw StoreMigrationFailure.maintenanceRequired(.invalidPointer)
        }
        guard case .v3(let pointer, let pointerData) = current,
              pointer.storeSchemaVersion == completedVersion,
              canonicalUUID(from: pointer.generationID)
                == completed.targetGenerationID else {
            throw StoreMigrationFailure.maintenanceRequired(.invalidPointer)
        }
        let retiredIDs = try authority.retiredGenerationIDs()
        let retired = RetiredPointerV1(
            generationIDs: retiredIDs
                .map { canonicalString(for: $0) }
                .sorted(),
            schemaVersion: StorePointerSchemaRegistry.retiredVersion
        )
        return try beginMigration(
            sourcePointer: pointer,
            sourcePointerData: pointerData,
            retired: retired,
            dataRootURL: dataRootURL,
            store: store,
            processID: processID
        )
    }

    @MainActor
    private func finishMigration(
        _ journal: StoreMigrationJournalV1,
        authority: StoreRestoreGenerationAuthority,
        store: StoreMigrationJournalStoreV1
    ) throws {
        let retired = try authority.retiredGenerationIDs()
        if !retired.contains(journal.sourceGenerationID) {
            let registry = try makeGenerationLeaseRegistry()
            try registry.withNoMigrationReservation {
                try authority.retireGeneration(
                    oldID: journal.sourceGenerationID,
                    currentID: journal.targetGenerationID
                )
            }
        }
        try reachMigrationBoundary(.beforeJournalRemoval)
        try store.removeJournal(expected: journal)
        try reachMigrationBoundary(.afterJournalRemoval)
        let current = try decodeCurrentPointer(
            at: dataRootURL.appendingPathComponent(Self.currentPointerName)
        )
        if case .v2(let pointer, _) = current {
            _ = try enrichCurrentPointer(pointer)
        }
    }

    @MainActor
    private func openPublishedMigrationTarget(
        _ journal: StoreMigrationJournalV1,
        dataRootURL: URL,
        store: StoreMigrationJournalStoreV1
    ) throws -> StoreGenerationSession {
        let envelope = try decodeCurrentPointer(
            at: dataRootURL.appendingPathComponent(Self.currentPointerName)
        )
        guard StoreMigrationCanonicalJSONV1.sha256(envelope.data)
                == journal.desiredPointerDigest,
              envelope.generationID
                == canonicalString(for: journal.targetGenerationID) else {
            throw StoreMigrationFailure.maintenanceRequired(.invalidPointer)
        }
        switch envelope {
        case .v2(let pointer, _):
            guard journal.targetRelease == .v2,
                  pointer.generationManifestSHA256 == journal.targetManifestDigest else {
                throw StoreMigrationFailure.maintenanceRequired(.invalidPointer)
            }
            return try openValidatedV2Current(
                pointer: pointer,
                dataRootURL: dataRootURL,
                store: store,
                identity: try compatibilityIdentity(for: pointer)
            )
        case .v3(let pointer, _):
            guard [.v3, .v4, .v5, .v6, .v7, .v8, .v9, .v10, .v11, .v12, .v13, .v14, .v15, .v16, .v17, .v18, .v19, .v20, .v21, .v22, .v23, .v24, .v25, .v26, .v27, .v28, .v29, .v30, .v31, .v32, .v33, .v34, .v35, .v36, .v37, .v38, .v39, .v40, .v41, .v42, .v43, .v44, .v45, .v46].contains(journal.targetRelease),
                  pointer.generationManifestSHA256 == journal.targetManifestDigest else {
                throw StoreMigrationFailure.maintenanceRequired(.invalidPointer)
            }
            return try openValidatedV3Current(
                pointer: pointer,
                dataRootURL: dataRootURL,
                store: store
            )
        case .legacy:
            throw StoreMigrationFailure.maintenanceRequired(.invalidPointer)
        }
    }

    private func requireMigrationPointerState(
        _ journal: StoreMigrationJournalV1
    ) throws {
        let envelope = try decodeCurrentPointer(
            at: dataRootURL.appendingPathComponent(Self.currentPointerName)
        )
        let data = envelope.data
        let digest = StoreMigrationCanonicalJSONV1.sha256(data)
        if journal.phase.isAtLeast(.pointerPublished) {
            guard digest == journal.desiredPointerDigest else {
                throw StoreMigrationFailure.maintenanceRequired(.invalidPointer)
            }
        } else if journal.phase == .generationInstalled,
                  journal.pointerPublicationAttempted {
            guard digest == journal.expectedPointerDigest
                    || digest == journal.desiredPointerDigest else {
                throw StoreMigrationFailure.maintenanceRequired(.invalidPointer)
            }
        } else {
            guard digest == journal.expectedPointerDigest else {
                throw StoreMigrationFailure.maintenanceRequired(.invalidPointer)
            }
        }
    }

    @MainActor
    private func requireSourceManifest(
        _ journal: StoreMigrationJournalV1,
        store: StoreMigrationJournalStoreV1
    ) throws -> StoreGenerationManifestV1 {
        let manifest = try store.loadManifest(
            targetGenerationID: journal.sourceGenerationID,
            expectedDigest: journal.sourceManifestDigest
        )
        guard manifest.schemaVersion == 1, manifest.generationID == journal.sourceGenerationID,
              manifest.migrationID == journal.migrationID,
              manifest.storeSchemaRelease == journal.sourceRelease,
              manifest.frozenIdentityDigest == journal.frozenIdentityDigest,
              (journal.sourceRelease == .v1
                ? manifest.semanticSHA256 == nil
                : manifest.semanticSHA256 != nil) else {
            throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
        }
        return manifest
    }

    private func requiredSourceSemanticDigest(
        _ journal: StoreMigrationJournalV1
    ) throws -> String {
        guard let digest = journal.sourceSemanticDigest,
              StoreMigrationCanonicalJSONV1.isLowercaseSHA256(digest) else {
            throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
        }
        return digest
    }

    @MainActor
    private func requireTargetManifest(
        _ journal: StoreMigrationJournalV1,
        store: StoreMigrationJournalStoreV1
    ) throws -> StoreGenerationManifestV1 {
        guard let digest = journal.targetManifestDigest,
              let semantic = journal.targetSemanticDigest else {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
        let manifest = try store.loadManifest(
            targetGenerationID: journal.targetGenerationID,
            expectedDigest: digest
        )
        guard manifest.schemaVersion == 1, manifest.generationID == journal.targetGenerationID,
              manifest.predecessorGenerationID == journal.sourceGenerationID,
              manifest.migrationID == journal.migrationID,
              manifest.storeSchemaRelease == journal.targetRelease,
              manifest.semanticSHA256 == semantic else {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
        return manifest
    }

    private func requireTargetGenerationSnapshot(
        _ journal: StoreMigrationJournalV1,
        manifest: StoreGenerationManifestV1,
        at generationRootURL: URL
    ) throws {
        guard manifest.schemaVersion == 1, manifest.generationID == journal.targetGenerationID,
              manifest.files == (try generationFileDigests(
                  at: generationRootURL,
                  durable: true
              )),
              manifest.frozenIdentityDigest
                == (try frozenIdentityDigest(for: generationRootURL)) else {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
    }

    private func migrationJournal(
        _ value: StoreMigrationJournalV1,
        phase: StoreMigrationPhaseV1,
        sourceSemanticDigest: String? = nil,
        targetManifestDigest: String? = nil,
        targetSemanticDigest: String? = nil,
        desiredPointerDigest: String? = nil,
        publicationProcessID: UUID? = nil,
        firstValidationProcessID: UUID? = nil,
        secondValidationProcessID: UUID? = nil,
        targetWritePossible: Bool? = nil,
        pointerPublicationAttempted: Bool? = nil
    ) throws -> StoreMigrationJournalV1 {
        try StoreMigrationJournalV1(
            schemaVersion: value.schemaVersion,
            migrationID: value.migrationID,
            sourceGenerationID: value.sourceGenerationID,
            targetGenerationID: value.targetGenerationID,
            sourceRelease: value.sourceRelease,
            targetRelease: value.targetRelease,
            sourcePointerDigest: value.sourcePointerDigest,
            sourceTreeDigest: value.sourceTreeDigest,
            sourceManifestDigest: value.sourceManifestDigest,
            sourceSemanticDigest: sourceSemanticDigest ?? value.sourceSemanticDigest,
            targetManifestDigest: targetManifestDigest ?? value.targetManifestDigest,
            targetSemanticDigest: targetSemanticDigest ?? value.targetSemanticDigest,
            frozenIdentityDigest: value.frozenIdentityDigest,
            expectedPointerDigest: value.expectedPointerDigest,
            desiredPointerDigest: desiredPointerDigest ?? value.desiredPointerDigest,
            originatingProcessID: value.originatingProcessID,
            publicationProcessID: publicationProcessID ?? value.publicationProcessID,
            firstValidationProcessID:
                firstValidationProcessID ?? value.firstValidationProcessID,
            secondValidationProcessID:
                secondValidationProcessID ?? value.secondValidationProcessID,
            phase: phase,
            targetWritePossible: targetWritePossible ?? value.targetWritePossible,
            pointerPublicationAttempted:
                pointerPublicationAttempted ?? value.pointerPublicationAttempted
        )
    }

    @MainActor
    private func publishMigrationPointerForwardOnly(
        _ journal: StoreMigrationJournalV1,
        store: StoreMigrationJournalStoreV1
    ) throws {
        let registry = try makeGenerationLeaseRegistry()
        try registry.withNoMigrationReservation {
            try publishMigrationPointerForwardOnlyLocked(journal, store: store)
        }
    }

    @MainActor
    private func publishMigrationPointerForwardOnlyLocked(
        _ journal: StoreMigrationJournalV1,
        store: StoreMigrationJournalStoreV1
    ) throws {
        let manifest = try requireTargetManifest(journal, store: store)
        guard let manifestDigest = journal.targetManifestDigest else {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
        let desiredData = try desiredMigrationPointerData(
            journal: journal,
            manifestDigest: manifestDigest
        )
        guard StoreMigrationCanonicalJSONV1.sha256(desiredData)
                == journal.desiredPointerDigest else {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }

        Self.pointerMutationLock.lock()
        defer { Self.pointerMutationLock.unlock() }
        let root = dataRootURL
        let parent = try openOwnedDirectory(at: root)
        defer { _ = Darwin.close(parent) }
        try verifyOwnedDirectory(at: root, descriptor: parent)
        let currentName = Self.currentPointerName
        let temporaryName = ".current.json.migration-next"
        let targetURL = root.appendingPathComponent(currentName, isDirectory: false)
        let temporaryURL = root.appendingPathComponent(temporaryName, isDirectory: false)
        try protectPointer(at: targetURL, parent: parent, root: root)
        let current = try StoreRestoreGenerationAuthority.readRegularFileWithIdentity(
            parent: parent,
            name: currentName
        )
        let currentDigest = StoreMigrationCanonicalJSONV1.sha256(current.data)
        if currentDigest == journal.desiredPointerDigest {
            guard current.data == desiredData else {
                throw StoreMigrationFailure.maintenanceRequired(.invalidPointer)
            }
            if try StoreRestoreGenerationAuthority.itemExists(
                parent: parent,
                name: temporaryName
            ) {
                let displaced = try StoreRestoreGenerationAuthority
                    .readRegularFileWithIdentity(
                        parent: parent,
                        name: temporaryName
                    )
                guard StoreMigrationCanonicalJSONV1.sha256(displaced.data)
                        == journal.expectedPointerDigest else {
                    throw StoreMigrationFailure.maintenanceRequired(
                        .forwardFixRequired
                    )
                }
                try removeOwnedEntry(parent: parent, name: temporaryName)
            }
            return
        }
        guard currentDigest == journal.expectedPointerDigest else {
            throw StoreMigrationFailure.maintenanceRequired(.invalidPointer)
        }
        if try StoreRestoreGenerationAuthority.itemExists(
            parent: parent,
            name: temporaryName
        ) {
            let existing = try StoreRestoreGenerationAuthority
                .readRegularFileWithIdentity(parent: parent, name: temporaryName)
            guard existing.data == desiredData else {
                throw StoreMigrationFailure.maintenanceRequired(.forwardFixRequired)
            }
            try removeOwnedEntry(parent: parent, name: temporaryName)
        }
        var publicationMayHaveOccurred = false
        do {
            try StoreRestoreGenerationAuthority.createRegularFile(
                parent: parent,
                name: temporaryName,
                data: desiredData
            )
            try protectPointerFile(
                .generationPointerTemporary,
                at: temporaryURL,
                parent: parent,
                root: root
            )
            let desiredIdentity = try StoreRestoreGenerationAuthority.regularFileIdentity(
                parent: parent,
                name: temporaryName
            )
            let currentBeforeSwap = try StoreRestoreGenerationAuthority
                .readRegularFileWithIdentity(parent: parent, name: currentName)
            guard currentBeforeSwap.data == current.data,
                  currentBeforeSwap.identity == current.identity,
                  Darwin.renameatx_np(
                      parent,
                      temporaryName,
                      parent,
                      currentName,
                      UInt32(RENAME_SWAP)
                  ) == 0 else {
                throw StoreMigrationFailure.maintenanceRequired(.invalidPointer)
            }
            publicationMayHaveOccurred = true
            guard Darwin.fsync(parent) == 0 else {
                throw StoreMigrationFailure.maintenanceRequired(.forwardFixRequired)
            }
            try protectPointer(at: targetURL, parent: parent, root: root)
            let published = try StoreRestoreGenerationAuthority.readRegularFileWithIdentity(
                parent: parent,
                name: currentName
            )
            let displaced = try StoreRestoreGenerationAuthority.readRegularFileWithIdentity(
                parent: parent,
                name: temporaryName
            )
            guard published.data == desiredData,
                  published.identity == desiredIdentity,
                  displaced.data == current.data,
                  displaced.identity == current.identity else {
                throw StoreMigrationFailure.maintenanceRequired(.forwardFixRequired)
            }
            try removeOwnedEntry(parent: parent, name: temporaryName)
        } catch {
            if publicationMayHaveOccurred {
                throw StoreMigrationFailure.maintenanceRequired(.forwardFixRequired)
            }
            if (try? StoreRestoreGenerationAuthority.itemExists(
                parent: parent,
                name: temporaryName
            )) == true {
                try? removeOwnedEntry(parent: parent, name: temporaryName)
            }
            throw error
        }
    }

    private func desiredMigrationPointerData(
        journal: StoreMigrationJournalV1,
        manifestDigest: String
    ) throws -> Data {
        switch (journal.sourceRelease, journal.targetRelease) {
        case (.v1, .v2):
            return try CurrentGenerationPointerV2(
                generationID: journal.targetGenerationID,
                generationManifestSHA256: manifestDigest
            ).canonicalData()
        case (.v2, .v3):
            let current = try decodeCurrentPointer(
                at: dataRootURL.appendingPathComponent(Self.currentPointerName)
            )
            guard case .v3(let pointer, let data) = current else {
                throw StoreMigrationFailure.maintenanceRequired(.invalidPointer)
            }
            let digest = StoreMigrationCanonicalJSONV1.sha256(data)
            let isSource = digest == journal.expectedPointerDigest
                && pointer.generationID
                    == canonicalString(for: journal.sourceGenerationID)
                && pointer.storeSchemaVersion == 2
            let isTarget = digest == journal.desiredPointerDigest
                && pointer.generationID
                    == canonicalString(for: journal.targetGenerationID)
                && pointer.storeSchemaVersion == 3
            guard isSource || isTarget else {
                throw StoreMigrationFailure.maintenanceRequired(.invalidPointer)
            }
            let identity = try pointer.identity()
            return try CurrentGenerationPointerV3(
                generationID: journal.targetGenerationID,
                generationManifestSHA256: manifestDigest,
                workspaceID: identity.workspaceID,
                replicaID: identity.replicaID,
                knownReplicaIDs: try pointer.knownReplicaIdentitySet(),
                storeSchemaVersion: 3
