        if release == .v10 { return try semanticExportV10(in: context, purpose: purpose) }
        if release == .v9 { return try semanticExportV9(in: context, purpose: purpose) }
        if release == .v8 { return try semanticExportV8(in: context, purpose: purpose) }
        if release == .v7 { return try semanticExportV7(in: context, purpose: purpose) }
        if release == .v6 { return try semanticExportV6(in: context, purpose: purpose) }
        if release == .v5 { return try semanticExportV5(in: context, purpose: purpose) }
        if release == .v4 { return try semanticExportV4(in: context, purpose: purpose) }
        if release == .v3 { return try semanticExportV3(in: context, purpose: purpose) }
        return try semanticExport(in: context)
    }

    @MainActor
    private func semanticExport(in context: ModelContext) throws -> Data {
        let records = try frozenPreV6SemanticRecords(in: context)
        return try BackupCanonicalEncoderV1().encodeRecords(records).data
    }

