                marker = try requireV53Marker(in: container.mainContext,expectedMigrationID:manifest.migrationID)
            case .v1:
                throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
            }
            // The fetched marker remains backed by this container until its
            // value is copied. Do not retain only a temporary container's context.
            return try withExtendedLifetime(container) { () throws -> UUID in
                guard let value = marker.migrationID else {
                    throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
                }
                return value
            }
        }
        diagnosticPhase?("manifest.identity")
        guard manifest.generationID == generationID,
               manifest.predecessorGenerationID == expectedOldID,
               manifest.migrationID == markerMigrationID else {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
        diagnosticPhase?("manifest.semantic")
        guard manifest.semanticSHA256 == (try semanticDigest(
                   at: modelStoreURL,
                   manifest: manifest
               )) else {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
        diagnosticPhase?("manifest.files")
        let observedFiles: [StoreGenerationFileDigestV1]
        do {
            observedFiles = try generationFileDigests(
                at: root,
                durable: true,
                restoreProof: restoreProof,
                restoreFileSnapshot: restoreFileSnapshot
            )
        } catch {
#if DEBUG
            emitEraseFileSnapshot(
                generationID: generationID,
                stage: .afterManifestSemantic,
                manifestObservation: .present,
                expectedFiles: manifest.files,
                observedFiles: nil,
                filesAcquisitionError: EraseFileSnapshotErrorV1(error),
                diagnosticPhase: diagnosticPhase
            )
#endif
            throw error
        }
#if DEBUG
        emitEraseFileSnapshot(
            generationID: generationID,
            stage: .afterManifestSemantic,
            manifestObservation: .present,
            expectedFiles: manifest.files,
            observedFiles: observedFiles,
            diagnosticPhase: diagnosticPhase
        )
#endif
        guard manifest.files == observedFiles else {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
        diagnosticPhase?("manifest.frozen-identity")
        guard manifest.frozenIdentityDigest == (try frozenIdentityDigest(
                   for: root,
                   restoreProof: restoreProof,
                   restoreFileSnapshot: restoreFileSnapshot
               )) else {
            throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
        }
        diagnosticPhase?("manifest.post-protection")
        if restoreProof == nil {
            try protectGeneration(at: root, staging: staging, requireModel: true)
        } else {
            _ = try requireRestoreFileSnapshot(
                restoreFileSnapshot,
                generationID: generationID,
                at: root,
                restoreProof: restoreProof
            )
        }
    }

