@MainActor
enum StoreStartupOpenResultV1 {
    case ready(StoreGenerationSession)
    case awaitingIndependentValidation(StoreMigrationAwaitingValidationV1)
}

/// A short-lived original-schema recovery capability, never an application
/// session. Retaining its context or mutation guard prevents source freezing.
@MainActor
final class StoreMigrationSourceRecoveryAuthorityV1 {
    let sourceGenerationID: UUID
    let sourceRelease: PersistentSchemaReleaseV1
    let generationRootURL: URL
    private var container: ModelContainer?
    private var context: ModelContext?
    private var guardValue: StoreMigrationSourceMutationGuardV1?

    fileprivate init(journal: StoreAggregateMigrationJournalV1, generationRootURL: URL,
                     container: ModelContainer, mutationGuard: StoreMigrationSourceMutationGuardV1) {
        sourceGenerationID = journal.sourceGenerationID
        sourceRelease = journal.sourceRelease
        self.generationRootURL = generationRootURL
        self.container = container
        context = container.mainContext
        context?.autosaveEnabled = false
        guardValue = mutationGuard
    }
    func recoveryContext() throws -> ModelContext {
        guard let context, let guardValue else { throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch) }
        try guardValue.validateCurrent()
        return context
    }
    func recoveryMutationGuard() throws -> StoreMigrationSourceMutationGuardV1 {
        guard let guardValue else { throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch) }
        try guardValue.validateCurrent()
        return guardValue
    }
    fileprivate func revokeAndRelease() throws {
        defer { context = nil; container = nil; guardValue = nil }
        try guardValue?.revoke()
    }
}

/// Only the factory's exact final-schema opener can construct this capability.
/// No caller can pair an unrelated context with a candidate reservation.
@MainActor
final class StoreMigrationFinalProjectionProofV1 {
    private let validated: StoreMigrationValidatedTerminalImagesV1
    private let journal: StoreAggregateMigrationJournalV1
    private let checkpointSHA256: String
    private let reprove: () throws -> Void
    private var consumed = false
    private var revoked = false

    fileprivate init(validated: StoreMigrationValidatedTerminalImagesV1,
                     journal: StoreAggregateMigrationJournalV1, reprove: @escaping () throws -> Void) throws {
        guard let checkpoint = journal.sourceCheckpoint, journal.candidateRootDevice != nil,
              journal.candidateRootInode != nil, journal.authorizedTargetRelease == journal.targetRelease else {
            throw StoreMigrationFailure.invalidContract
        }
        self.validated = validated; self.journal = journal; self.reprove = reprove
        checkpointSHA256 = try StoreMigrationCanonicalJSONV1.digest(checkpoint)
    }

    fileprivate func withValidatedSource<Value>(expected: StoreAggregateMigrationJournalV1,
        _ body: (StoreMigrationValidatedTerminalImagesV1) throws -> Value) throws -> Value {
        guard !revoked, expected == journal, let checkpoint = expected.sourceCheckpoint,
              try StoreMigrationCanonicalJSONV1.digest(checkpoint) == checkpointSHA256 else {
            throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
        }
        try reprove()
        let value = try body(validated)
        try reprove()
        return value
    }

    fileprivate func consumeForCandidateNormalization<Value>(expected: StoreAggregateMigrationJournalV1,
        _ body: (StoreMigrationValidatedTerminalImagesV1) throws -> Value) throws -> Value {
        guard !consumed else { throw StoreMigrationFailure.invalidPhaseTransition }
        consumed = true
        return try withValidatedSource(expected: expected, body)
    }

    fileprivate func revoke() { revoked = true }
}

@MainActor
final class StoreMigrationFinalCandidateAuthorityV1 {
    private let container: ModelContainer
    private let registry: GenerationLeaseRegistryV1
    private let journal: StoreAggregateMigrationJournalV1
    private let reprove: () throws -> Void
    private let projectionProof: StoreMigrationFinalProjectionProofV1

    fileprivate init(container: ModelContainer, registry: GenerationLeaseRegistryV1,
                     journal: StoreAggregateMigrationJournalV1, projectionProof: StoreMigrationFinalProjectionProofV1,
                     reprove: @escaping () throws -> Void) {
        self.container = container; self.registry = registry; self.journal = journal; self.reprove = reprove
        self.projectionProof = projectionProof
    }

    func withValidatedTerminalImages<Value>(_ body: (StoreMigrationValidatedTerminalImagesV1) throws -> Value) throws -> Value {
        try projectionProof.withValidatedSource(expected: journal, body)
    }

    func consumeTerminalNormalization<Value>(_ body: (StoreMigrationValidatedTerminalImagesV1) throws -> Value) throws -> Value {
        try projectionProof.consumeForCandidateNormalization(expected: journal, body)
    }

    func withAuthorizedContext<Value>(_ body: (ModelContext, StoreAggregateMigrationJournalV1) throws -> Value) throws -> Value {
        try projectionProof.withValidatedSource(expected: journal) { _ in
            try registry.withMigrationReservation(expected: journal) {
                try reprove()
                let result = try body(container.mainContext, journal)
                try reprove()
                return result
            }
        }
    }
}

/// One-shot read capability constructed from the actual released schema and
/// immutable activation lineage. It has no save configuration or writer lease.
@MainActor
final class StoreMigrationHistoricalCheckpointAuthorityV1 {
    private var container: ModelContainer?
    private var context: ModelContext?
    private let journal: StoreAggregateMigrationJournalV1
    private let registry: GenerationLeaseRegistryV1
    private let control: StoreAggregateMigrationControlV1
    private let bindingProof: () throws -> Void
    private let legacyV10BaselineProof: () throws -> Void
    private let observationPrediction: (UUID) throws -> ObservationAndTimeMigrationResultV1
    private let assurancePrediction: (UUID) throws -> StoreMigrationLegacyAssurancePredictionV1
    private let assetPrediction: (UUID) throws -> AssetSemanticPersistentSnapshotV1
    private var used = false
    private var activeRead = false
    private var revoked = false

    fileprivate init(container: ModelContainer, journal: StoreAggregateMigrationJournalV1,
                     registry: GenerationLeaseRegistryV1, control: StoreAggregateMigrationControlV1,
                     bindingProof: @escaping () throws -> Void,
                     legacyV10BaselineProof: @escaping () throws -> Void,
                     observationPrediction: @escaping (UUID) throws -> ObservationAndTimeMigrationResultV1,
                     assurancePrediction: @escaping (UUID) throws -> StoreMigrationLegacyAssurancePredictionV1,
                     assetPrediction: @escaping (UUID) throws -> AssetSemanticPersistentSnapshotV1) {
        self.container = container; context = container.mainContext
        self.journal = journal; self.registry = registry; self.control = control
        self.bindingProof = bindingProof; self.legacyV10BaselineProof = legacyV10BaselineProof
        self.observationPrediction = observationPrediction; self.assurancePrediction = assurancePrediction
        self.assetPrediction = assetPrediction
    }

    private func predictedValue<Value>(_ body: () throws -> Value) throws -> Value {
        guard activeRead, !revoked else { throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch) }
        try bindingProof()
        let value = try body()
        try bindingProof()
        return value
    }

    func predictedObservationAndTime(recordID: UUID) throws -> ObservationAndTimeMigrationResultV1 {
        try predictedValue { try observationPrediction(recordID) }
    }

    func predictedLegacyAssurance(recordID: UUID) throws -> StoreMigrationLegacyAssurancePredictionV1 {
        try predictedValue { try assurancePrediction(recordID) }
    }

    func predictedLegacyAssetSemantics(assetID: UUID) throws -> AssetSemanticPersistentSnapshotV1 {
        try predictedValue { try assetPrediction(assetID) }
    }

    func withReadContext<Value>(_ body: (ModelContext, PersistentSchemaReleaseV1, UUID, WorkspaceReplicaIdentityV1) throws -> Value) throws -> Value {
        guard !used, !revoked, let context, !context.autosaveEnabled, !context.hasChanges else {
            throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
        }
        used = true
        return try registry.withMigrationReservation(expected: journal) {
            try control.withOriginalSource(journal) {
                try bindingProof()
                activeRead = true
                defer { activeRead = false; context.rollback() }
                let result = try body(context, journal.sourceRelease, journal.sourceGenerationID, journal.identity())
                guard !context.hasChanges else { throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch) }
                try bindingProof()
                return result
            }
        }
    }

    func requireOriginalV10LegacyBaseline() throws {
        guard activeRead, !revoked, journal.sourceRelease.versionIdentifier.major >= 10 else {
            throw StoreMigrationFailure.maintenanceRequired(.sourceMismatch)
        }
        try bindingProof()
        try legacyV10BaselineProof()
        try bindingProof()
    }

    fileprivate func revokeAndRelease() {
        revoked = true; activeRead = false; context = nil; container = nil
    }
}

@MainActor
private final class StoreMigrationSourceDrainProofV1 {
    // Keep the established owner-liveness guard until even an escaped raw
    // context has gone away, independently of the factory's lifetime.
    private let registry: GenerationLeaseRegistryV1
    private weak var context: ModelContext?
    private weak var container: ModelContainer?
    private weak var mutationGuard: StoreMigrationSourceMutationGuardV1?
    init(container: ModelContainer, mutationGuard: StoreMigrationSourceMutationGuardV1,
         registry: GenerationLeaseRegistryV1) {
        self.registry = registry
        context = container.mainContext; self.container = container; self.mutationGuard = mutationGuard
    }
    init(readOnlyContainer: ModelContainer, registry: GenerationLeaseRegistryV1) {
        self.registry = registry; context = readOnlyContainer.mainContext; container = readOnlyContainer
    }
    var isDrained: Bool { context == nil && container == nil && mutationGuard == nil }
#if DEBUG
    var diagnosticFacts: String {
        "contextReleased=\(context == nil) containerReleased=\(container == nil) mutationGuardReleased=\(mutationGuard == nil)"
    }
#endif
}

/// Initial Erase inventory only. Minted inside the factory's fixed read under G,
/// bound to its exact context, and revoked before that context is drained.
@MainActor
final class ErasePreexistingRetiredSourceValidationV1 {
    let generationRootURL: URL
    let workspaceIdentity: WorkspaceReplicaIdentityV1
    private let factory: StoreGenerationFactory
    private let authority: StoreRestoreGenerationAuthority
    private let registry: GenerationLeaseRegistryV1
    private let manifestStore: StoreMigrationJournalStoreV1
    private let manifest: StoreGenerationManifestV1
    private let epoch: GenerationEpochV1
    private let reader: GenerationLeaseTokenV1
    private let pointer: CurrentGenerationPointerV3
    private let retiredIDs: [UUID]
    private let rootDescriptor: Int32
    private let rootIdentity: StoreRestoreGenerationAuthority.Identity
    private let currentRootIdentity: StreamingArchiveRootIdentityV1
    private let modelIdentity: StoreRestoreGenerationAuthority.RegularFileIdentity
    private weak var context: ModelContext?
    private let history: MutationHistorySnapshotV1
    private let workspaceRevision: Int64
    private let localSequence: Int64
    private let mutableSemanticSHA256: String?
    private var active = true

    private init(factory: StoreGenerationFactory, authority: StoreRestoreGenerationAuthority,
        session: StoreGenerationSession, manifestStore: StoreMigrationJournalStoreV1,
        manifest: StoreGenerationManifestV1, epoch: GenerationEpochV1,
        reader: GenerationLeaseTokenV1, pointer: CurrentGenerationPointerV3,
        retiredIDs: [UUID], rootDescriptor: Int32,
        rootIdentity: StoreRestoreGenerationAuthority.Identity,
        currentRootIdentity: StreamingArchiveRootIdentityV1,
        identity: WorkspaceReplicaIdentityV1, history: MutationHistorySnapshotV1,
        state: WorkspaceMutationStateRow
    ) throws {
        self.factory = factory; self.authority = authority
        registry = try factory.makeGenerationLeaseRegistry()
        self.manifestStore = manifestStore; self.manifest = manifest
        self.epoch = epoch; self.reader = reader; self.pointer = pointer
        self.retiredIDs = retiredIDs; self.rootDescriptor = rootDescriptor
        self.rootIdentity = rootIdentity; self.currentRootIdentity = currentRootIdentity
        modelIdentity = try StoreRestoreGenerationAuthority.regularFileIdentity(
            parent: rootDescriptor, name: "model.sqlite")
        context = session.modelContext; generationRootURL = session.generationRootURL
        workspaceIdentity = identity; self.history = history
        workspaceRevision = state.workspaceRevision; localSequence = state.lastLocalSequence
        mutableSemanticSHA256 = state.mutableSemanticSHA256
    }

    deinit { _ = Darwin.close(rootDescriptor) }

    fileprivate static func acquire(factory: StoreGenerationFactory,
        authority: StoreRestoreGenerationAuthority, session: StoreGenerationSession,
        expectedCurrentID: UUID, expectedRetiredIDs: [UUID]
    ) throws -> ErasePreexistingRetiredSourceValidationV1 {
        let id = session.generationID
        guard id != expectedCurrentID, expectedRetiredIDs.contains(id),
              try authority.retiredGenerationIDs() == expectedRetiredIDs,
              session.storeSchemaRelease == .v53,
              let epoch = session.generationEpoch, let reader = session.readerLeaseToken,
              reader.epoch == epoch, epoch.generationID == id else {
            throw EraseAllServiceError.invalidAuthority
        }
        let pointer = try factory.currentGenerationPointerV3(
            expectedGenerationID: expectedCurrentID, authority: authority)
        let store = try StoreMigrationJournalStoreV1(applicationSupportURL: factory.restoreApplicationSupportURL)
        let manifest = try store.loadManifest(targetGenerationID: id,
            expectedDigest: epoch.generationManifestSHA256)
        guard manifest.generationID == id, manifest.storeSchemaRelease == .v53 else {
            throw EraseAllServiceError.invalidAuthority
        }
        let descriptor = Darwin.open(session.generationRootURL.path, O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
        guard descriptor >= 0 else { throw EraseAllServiceError.invalidAuthority }
        var transferred = false
        defer { if !transferred { _ = Darwin.close(descriptor) } }
        let root = try StoreRestoreGenerationAuthority.directoryIdentity(descriptor: descriptor)
        let currentRoot = try authority.restoreGenerationRootIdentity(id: expectedCurrentID, staging: false)
        try factory.reprovePreexistingRetiredRoot(id: id, descriptor: descriptor, expectedIdentity: root)
        let identity = try factory.acceptedV53SemanticIdentity(in: session.modelContext,
            generationID: id, migrationID: manifest.migrationID)
        let journal = try MutationJournalStoreV1(modelContext: session.modelContext,
            identity: identity, generationID: id, allowStateBootstrap: false)
        let history = try journal.exportSnapshot()
        let states = try session.modelContext.fetch(FetchDescriptor<WorkspaceMutationStateRow>())
        guard states.count == 1, let state = states.first else { throw EraseAllServiceError.invalidAuthority }
        let result = try ErasePreexistingRetiredSourceValidationV1(factory: factory,
            authority: authority, session: session, manifestStore: store, manifest: manifest,
            epoch: epoch, reader: reader, pointer: pointer, retiredIDs: expectedRetiredIDs,
            rootDescriptor: descriptor, rootIdentity: root, currentRootIdentity: currentRoot,
            identity: identity, history: history, state: state)
        transferred = true
        try result.revalidate(modelContext: session.modelContext)
        return result
    }

    fileprivate func invalidate() { active = false }

    func revalidate(modelContext: ModelContext) throws {
        guard active, context === modelContext, !modelContext.hasChanges else {
            throw EraseAllServiceError.invalidAuthority
        }
        try revalidateControls()
        let configurations = Array(modelContext.container.configurations)
        guard configurations.count == 1, !configurations[0].isStoredInMemoryOnly,
              configurations[0].url.standardizedFileURL
                == generationRootURL.appendingPathComponent("model.sqlite").standardizedFileURL,
              try factory.acceptedV53SemanticIdentity(in: modelContext,
                  generationID: epoch.generationID, migrationID: manifest.migrationID) == workspaceIdentity else {
            throw EraseAllServiceError.invalidAuthority
        }
        let states = try modelContext.fetch(FetchDescriptor<WorkspaceMutationStateRow>())
        guard states.count == 1, let state = states.first,
              state.workspaceRevision == workspaceRevision, state.lastLocalSequence == localSequence,
              state.mutableSemanticSHA256 == mutableSemanticSHA256 else {
            throw EraseAllServiceError.invalidAuthority
        }
        let journal = try MutationJournalStoreV1(modelContext: modelContext,
            identity: workspaceIdentity, generationID: epoch.generationID, allowStateBootstrap: false)
        guard try journal.exportSnapshot() == history, !modelContext.hasChanges else {
            throw EraseAllServiceError.invalidAuthority
        }
        try revalidateControls()
    }

    private func revalidateControls() throws {
        try authority.verify()
        try authority.requireNoRestoreJournal()
        try authority.requireNoEraseAuthority()
        try registry.validateActive(reader, requiredRole: .reader)
        guard try authority.restoreGenerationNames().isEmpty,
              try authority.importStagingNames().isEmpty,
              try StoreRestoreGenerationAuthority.regularFileIdentity(
                  parent: rootDescriptor, name: "model.sqlite") == modelIdentity,
              let currentID = UUID(uuidString: pointer.generationID),
              try factory.currentGenerationPointerV3(expectedGenerationID: currentID, authority: authority) == pointer,
              try authority.retiredGenerationIDs() == retiredIDs,
              try Set(authority.installedGenerationNames())
                == Set(([currentID] + retiredIDs).map { $0.uuidString.lowercased() }),
              try authority.restoreGenerationRootIdentity(id: currentID, staging: false) == currentRootIdentity,
              try authority.restoreGenerationRootIdentity(id: epoch.generationID, staging: false)
                == StreamingArchiveRootIdentityV1(device: UInt64(rootIdentity.device), inode: UInt64(rootIdentity.inode)),
              try manifestStore.loadManifest(targetGenerationID: epoch.generationID,
                  expectedDigest: epoch.generationManifestSHA256) == manifest else {
            throw EraseAllServiceError.invalidAuthority
        }
        try factory.reprovePreexistingRetiredRoot(id: epoch.generationID,
            descriptor: rootDescriptor, expectedIdentity: rootIdentity)
        try authority.verify()
    }
}

/// Settled schema-2 Erase recovery only. Freshly minted under the same G,
/// bound to its exact context, and revoked before that context is drained.
@MainActor
final class EraseRecoveryRetiredSourceValidationV1 {
    let generationRootURL: URL
    let workspaceIdentity: WorkspaceReplicaIdentityV1
    private let factory: StoreGenerationFactory
    private let authority: StoreRestoreGenerationAuthority
    private let registry: GenerationLeaseRegistryV1
    private let manifestStore: StoreMigrationJournalStoreV1
    private let manifest: StoreGenerationManifestV1
    private let epoch: GenerationEpochV1
    private let reader: GenerationLeaseTokenV1
    private let intent: EraseIntentV1
    private let controls: Controls
    private let rootDescriptor: Int32
    private let rootIdentity: StoreRestoreGenerationAuthority.Identity
    private let modelIdentity: StoreRestoreGenerationAuthority.RegularFileIdentity
    private weak var context: ModelContext?
    private let history: MutationHistorySnapshotV1
    private let workspaceRevision: Int64
    private let localSequence: Int64
    private let mutableSemanticSHA256: String?
    private var active = true

    private init(factory: StoreGenerationFactory, authority: StoreRestoreGenerationAuthority,
        session: StoreGenerationSession, manifestStore: StoreMigrationJournalStoreV1,
        manifest: StoreGenerationManifestV1, epoch: GenerationEpochV1,
        reader: GenerationLeaseTokenV1, intent: EraseIntentV1, controls: Controls,
        rootDescriptor: Int32,
        rootIdentity: StoreRestoreGenerationAuthority.Identity,
        identity: WorkspaceReplicaIdentityV1, history: MutationHistorySnapshotV1,
        state: WorkspaceMutationStateRow
    ) throws {
        self.factory = factory; self.authority = authority
        registry = try factory.makeGenerationLeaseRegistry()
        self.manifestStore = manifestStore; self.manifest = manifest
        self.epoch = epoch; self.reader = reader; self.intent = intent; self.controls = controls
        self.rootDescriptor = rootDescriptor; self.rootIdentity = rootIdentity
        modelIdentity = try StoreRestoreGenerationAuthority.regularFileIdentity(
            parent: rootDescriptor, name: "model.sqlite")
        context = session.modelContext; generationRootURL = session.generationRootURL
        workspaceIdentity = identity; self.history = history
        workspaceRevision = state.workspaceRevision; localSequence = state.lastLocalSequence
        mutableSemanticSHA256 = state.mutableSemanticSHA256
    }

    deinit { _ = Darwin.close(rootDescriptor) }

    fileprivate static func acquire(factory: StoreGenerationFactory,
        authority: StoreRestoreGenerationAuthority, session: StoreGenerationSession,
        intent: EraseIntentV1, expectedControls: Controls
    ) throws -> EraseRecoveryRetiredSourceValidationV1 {
        let id = session.generationID
        guard id != intent.oldGenerationID, id != intent.newGenerationID,
              intent.generationIDsToDelete.contains(id), expectedControls.retiredIDs.contains(id),
              session.storeSchemaRelease == .v53,
              let epoch = session.generationEpoch, let reader = session.readerLeaseToken,
              reader.epoch == epoch, epoch.generationID == id else {
            throw EraseAllServiceError.invalidAuthority
        }
        let controls = try captureControls(id: id, intent: intent, factory: factory, authority: authority)
        guard controls == expectedControls else { throw EraseAllServiceError.invalidAuthority }
        let store = try StoreMigrationJournalStoreV1(applicationSupportURL: factory.restoreApplicationSupportURL)
        let manifest = try store.loadManifest(targetGenerationID: id,
            expectedDigest: epoch.generationManifestSHA256)
        guard manifest.generationID == id, manifest.storeSchemaRelease == .v53 else {
            throw EraseAllServiceError.invalidAuthority
        }
        let descriptor = Darwin.open(session.generationRootURL.path, O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
        guard descriptor >= 0 else { throw EraseAllServiceError.invalidAuthority }
        var transferred = false
        defer { if !transferred { _ = Darwin.close(descriptor) } }
        let root = try StoreRestoreGenerationAuthority.directoryIdentity(descriptor: descriptor)
        try factory.reprovePreexistingRetiredRoot(id: id, descriptor: descriptor, expectedIdentity: root)
        let identity = try factory.acceptedV53SemanticIdentity(in: session.modelContext,
            generationID: id, migrationID: manifest.migrationID)
        let journal = try MutationJournalStoreV1(modelContext: session.modelContext,
            identity: identity, generationID: id, allowStateBootstrap: false)
        let history = try journal.exportSnapshot()
        let states = try session.modelContext.fetch(FetchDescriptor<WorkspaceMutationStateRow>())
        guard states.count == 1, let state = states.first else { throw EraseAllServiceError.invalidAuthority }
        let result = try EraseRecoveryRetiredSourceValidationV1(factory: factory,
            authority: authority, session: session, manifestStore: store, manifest: manifest,
            epoch: epoch, reader: reader, intent: intent, controls: controls,
            rootDescriptor: descriptor, rootIdentity: root,
            identity: identity, history: history, state: state)
        transferred = true
        try result.revalidate(modelContext: session.modelContext)
        return result
    }

    fileprivate func invalidate() { active = false }

    func revalidate(modelContext: ModelContext) throws {
        guard active, context === modelContext, !modelContext.hasChanges else {
            throw EraseAllServiceError.invalidAuthority
        }
        try revalidateControls()
        let configurations = Array(modelContext.container.configurations)
        guard configurations.count == 1, !configurations[0].isStoredInMemoryOnly,
              configurations[0].url.standardizedFileURL
                == generationRootURL.appendingPathComponent("model.sqlite").standardizedFileURL,
              try factory.acceptedV53SemanticIdentity(in: modelContext,
                  generationID: epoch.generationID, migrationID: manifest.migrationID) == workspaceIdentity else {
            throw EraseAllServiceError.invalidAuthority
        }
        let states = try modelContext.fetch(FetchDescriptor<WorkspaceMutationStateRow>())
        guard states.count == 1, let state = states.first,
              state.workspaceRevision == workspaceRevision, state.lastLocalSequence == localSequence,
              state.mutableSemanticSHA256 == mutableSemanticSHA256 else {
            throw EraseAllServiceError.invalidAuthority
        }
        let journal = try MutationJournalStoreV1(modelContext: modelContext,
            identity: workspaceIdentity, generationID: epoch.generationID, allowStateBootstrap: false)
        guard try journal.exportSnapshot() == history, !modelContext.hasChanges else {
            throw EraseAllServiceError.invalidAuthority
        }
        try revalidateControls()
    }

    private func revalidateControls() throws {
        try registry.validateActive(reader, requiredRole: .reader)
        guard try Self.captureControls(id: epoch.generationID, intent: intent,
                  factory: factory, authority: authority) == controls,
              try StoreRestoreGenerationAuthority.regularFileIdentity(
                  parent: rootDescriptor, name: "model.sqlite") == modelIdentity,
              try authority.restoreGenerationRootIdentity(id: epoch.generationID, staging: false)
                == StreamingArchiveRootIdentityV1(device: UInt64(rootIdentity.device), inode: UInt64(rootIdentity.inode)),
              try manifestStore.loadManifest(targetGenerationID: epoch.generationID,
                  expectedDigest: epoch.generationManifestSHA256) == manifest else {
            throw EraseAllServiceError.invalidAuthority
        }
        try factory.reprovePreexistingRetiredRoot(id: epoch.generationID,
            descriptor: rootDescriptor, expectedIdentity: rootIdentity)
        try authority.verify()
    }

    fileprivate struct Controls: Equatable {
        let pointer: CurrentGenerationPointerV3
        let retiredIDs: [UUID]
        let installedNames: [String]
        let preparation: ErasePreparationV2?
        let currentRoot: StreamingArchiveRootIdentityV1
        let targetRoot: StreamingArchiveRootIdentityV1
        let targetManifest: StoreGenerationManifestV1
    }

    /// Read only already-settled controls. This never promotes pending intent or
    /// preparation bytes and never treats oldPointer as another source's identity.
    fileprivate static func captureControls(id: UUID, intent: EraseIntentV1,
        factory: StoreGenerationFactory, authority: StoreRestoreGenerationAuthority
    ) throws -> Controls {
        guard intent.schemaVersion == 2, EraseIntentCodecV1.valid(intent),
              id != intent.oldGenerationID, id != intent.newGenerationID,
              intent.generationIDsToDelete.contains(id),
              let oldPointer = intent.oldPointer, let targetPointer = intent.targetPointer else {
            throw EraseAllServiceError.invalidAuthority
        }
        try authority.verify()
        try authority.requireNoRestoreJournal()
        try requireSettledControls(applicationSupportURL: factory.restoreApplicationSupportURL)
        let store = try EraseIntentStore(applicationSupportURL: factory.restoreApplicationSupportURL)
        guard try store.load() == intent else { throw EraseAllServiceError.invalidAuthority }
        let preparation = try store.loadPreparation()
        guard preparation?.matches(intent) == true,
              try authority.restoreGenerationNames().isEmpty,
              try authority.importStagingNames().isEmpty else {
            throw EraseAllServiceError.invalidAuthority
        }
        let currentID = try authority.currentGenerationID()
        let retired = try authority.retiredGenerationIDs()
        let installed = try authority.installedGenerationNames().sorted()
        let all = Set((intent.generationIDsToDelete + [intent.newGenerationID]).map { $0.uuidString.lowercased() })
        let names = Set(installed)
        let prior = intent.generationIDsToDelete.filter { $0 != intent.oldGenerationID }
        guard retired.contains(id), names.contains(id.uuidString.lowercased()),
              names.contains(intent.newGenerationID.uuidString.lowercased()), names.isSubset(of: all) else {
            throw EraseAllServiceError.invalidAuthority
        }
        let expected: RestorePointerIdentityV1
        switch intent.phase {
        case .emptyGenerationPrepared:
            guard names == all else { throw EraseAllServiceError.invalidAuthority }
            if currentID == intent.oldGenerationID {
                guard retired == prior else { throw EraseAllServiceError.invalidAuthority }
                expected = oldPointer
            } else if currentID == intent.newGenerationID {
                guard retired == prior || retired == intent.generationIDsToDelete else {
                    throw EraseAllServiceError.invalidAuthority
                }
                expected = targetPointer
            } else { throw EraseAllServiceError.invalidAuthority }
        case .pointerSwitched:
            guard currentID == intent.newGenerationID, names == all,
                  retired == intent.generationIDsToDelete else { throw EraseAllServiceError.invalidAuthority }
            expected = targetPointer
        case .sessionActivated:
            guard currentID == intent.newGenerationID, retired == intent.generationIDsToDelete else {
                throw EraseAllServiceError.invalidAuthority
            }
            // Some earlier deletion targets may already be gone. In particular,
            // this read must not require the immediate old-current root to exist.
            expected = targetPointer
        case .cleanupComplete:
            // This phase is durable only after every deletion target is absent.
            throw EraseAllServiceError.invalidAuthority
        }
        let pointer = try factory.currentGenerationPointerV3(expectedGenerationID: currentID, authority: authority)
        let expectedPointer = try CurrentGenerationPointerV3(generationID: expected.generationID,
            generationManifestSHA256: expected.generationManifestSHA256,
            workspaceID: WorkspaceID(rawValue: expected.workspaceID),
            replicaID: ReplicaID(rawValue: expected.replicaID),
            knownReplicaIDs: Set(expected.knownReplicaIDs.map { ReplicaID(rawValue: $0) }),
            storeSchemaVersion: PersistentSchemaReleaseRegistryV1.activeVersionIdentifier.major)
        guard pointer == expectedPointer else { throw EraseAllServiceError.invalidAuthority }
        let manifestStore = try StoreMigrationJournalStoreV1(applicationSupportURL: factory.restoreApplicationSupportURL)
        let targetManifest = try manifestStore.loadManifest(targetGenerationID: intent.newGenerationID,
            expectedDigest: targetPointer.generationManifestSHA256)
        guard targetManifest.generationID == intent.newGenerationID,
              targetManifest.storeSchemaRelease == .v53 else { throw EraseAllServiceError.invalidAuthority }
        let result = Controls(pointer: pointer, retiredIDs: retired, installedNames: installed,
            preparation: preparation,
            currentRoot: try authority.restoreGenerationRootIdentity(id: currentID, staging: false),
            targetRoot: try authority.restoreGenerationRootIdentity(id: intent.newGenerationID, staging: false),
            targetManifest: targetManifest)
        try requireSettledControls(applicationSupportURL: factory.restoreApplicationSupportURL)
        try authority.verify()
        return result
    }

    private static func requireSettledControls(applicationSupportURL: URL) throws {
        let app = Darwin.open(applicationSupportURL.path, O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
        guard app >= 0 else { throw EraseAllServiceError.invalidAuthority }
        defer { _ = Darwin.close(app) }
        let erase = Darwin.openat(app, "FieldEvidenceErase", O_RDONLY | O_DIRECTORY | O_NOFOLLOW)
        guard erase >= 0 else { throw EraseAllServiceError.invalidAuthority }
        defer { _ = Darwin.close(erase) }
        for name in ["erase.json", "preparation.json"] {
            var value = stat()
            guard Darwin.fstatat(erase, name, &value, AT_SYMLINK_NOFOLLOW) == 0,
                  value.st_mode & S_IFMT == S_IFREG, value.st_nlink == 1 else {
                throw EraseAllServiceError.invalidAuthority
            }
        }
        for name in [".erase.json.next", ".preparation.json.next"] {
            var value = stat()
            guard Darwin.fstatat(erase, name, &value, AT_SYMLINK_NOFOLLOW) != 0,
                  errno == ENOENT else { throw EraseAllServiceError.invalidAuthority }
        }
    }
}

@MainActor
private final class ErasePreexistingRetiredDrainProofV1 {
    private weak var session: StoreGenerationSession?
    private weak var context: ModelContext?
    private weak var container: ModelContainer?
    init(session: StoreGenerationSession) {
        self.session = session; context = session.modelContext; container = session.modelContext.container
    }
    var isDrained: Bool { session == nil && context == nil && container == nil }
}

/// The original P target is opened solely for its semantic empty-ledger proof.
/// Its SwiftData aliases must leave this exact synchronous frame before the
/// pointer writer freezes its physical Data sibling image. No lease is minted
/// for that still-private target, and a surviving alias refuses publication.
@MainActor
private final class OriginalEraseTargetPreflightDrainV1 {
    private weak var session: StoreGenerationSession?
    private weak var context: ModelContext?
    private weak var container: ModelContainer?

    init(session: StoreGenerationSession) throws {
        guard session.readerLeaseToken == nil,
              session.eraseRetirementReaderHandle == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        self.session = session
        context = session.modelContext
        container = session.modelContext.container
    }

    func requireDrained() throws {
        guard session == nil, context == nil, container == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }
}

/// Metadata for one admitted Erase. This is not an admission, drain or
/// completion capability; the Router and transferred exclusion retain those.
struct EraseRetirementBindingV1: Equatable, Sendable {
    let subject: EraseAllOperationSubjectV1
    let operationID: UUID
    let ownerMint: UUID
    let registryIdentity: StreamingArchiveRootIdentityV1
    let generationEpoch: GenerationEpochV1
    let workspaceIdentity: WorkspaceReplicaIdentityV1
}

fileprivate struct ErasePreparedTargetSnapshotV1: Equatable, Sendable {
    let facts: [StoreRestoreGenerationFileSnapshotV1.NodeFact]
    let files: [StoreGenerationFileDigestV1]

    func requireCurrent(_ current: Self, removalStarted: Bool) throws {
        guard let root = facts.first, current.facts.first == root else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        if removalStarted {
            // Recursive deletion may have removed a prefix of this exact
            // validated tree. It may not admit a new or changed survivor.
            guard current.facts.allSatisfy(facts.contains),
                  current.files.allSatisfy(files.contains) else {
                throw StoreGenerationFailure.dataPointerInvalid
            }
        } else {
            guard current == self else { throw StoreGenerationFailure.dataPointerInvalid }
        }
    }
}

@MainActor
final class ErasePreparedGenerationDiscardV1 {
    fileprivate let expectedOldPointer: RestorePointerIdentityV1
    fileprivate let targetGenerationID: UUID
    fileprivate let targetIdentity: WorkspaceReplicaIdentityV1
    fileprivate let expectedEmptyLedger: DeletionLedgerProofV2
    fileprivate let authority: StoreRestoreGenerationAuthority
    fileprivate let expectedNames: Set<String>
    fileprivate let store: StoreMigrationJournalStoreV1
    fileprivate let targetRootIdentity: ReportPDFAnchoredFile.RootIdentity?
    fileprivate let targetSnapshot: ErasePreparedTargetSnapshotV1?
    fileprivate var removalStarted = false
    fileprivate init(expectedOldPointer: RestorePointerIdentityV1, targetGenerationID: UUID,
        targetIdentity: WorkspaceReplicaIdentityV1, expectedEmptyLedger: DeletionLedgerProofV2,
        authority: StoreRestoreGenerationAuthority, expectedNames: Set<String>,
        store: StoreMigrationJournalStoreV1, targetRootIdentity: ReportPDFAnchoredFile.RootIdentity?,
        targetSnapshot: ErasePreparedTargetSnapshotV1? = nil) {
        self.expectedOldPointer = expectedOldPointer; self.targetGenerationID = targetGenerationID
        self.targetIdentity = targetIdentity; self.expectedEmptyLedger = expectedEmptyLedger
        self.authority = authority; self.expectedNames = expectedNames; self.store = store
        self.targetRootIdentity = targetRootIdentity
        self.targetSnapshot = targetSnapshot
    }
}

/// Captured before EX transfer. This retains only the original manifest-store
/// descriptors and immutable controls, never a session, context or callback.
/// Its private construction prevents substituting another root's manifest.
@MainActor
final class EraseCurrentManifestScopeV1 {
    let binding: EraseRetirementBindingV1
    fileprivate let pointerData: Data
#if DEBUG
    /// Immutable DATA for the fixed post-close observation only; source
    /// validation still uses the original manifest owner's fresh checks.
    var postClosePointerDataForTesting: Data { pointerData }
#endif
    fileprivate let store: StoreMigrationJournalStoreV1?

    fileprivate init(binding: EraseRetirementBindingV1, pointerData: Data,
                     store: StoreMigrationJournalStoreV1?) {
        self.binding = binding
        self.pointerData = pointerData
        self.store = store
    }
}

/// Each observation is weak all the way through SwiftData. A retained service,
/// raw context, or container therefore keeps retirement pending even after its
/// published coordinator has gone away.
@MainActor
fileprivate final class EraseSessionWeakObservationV1 {
    weak var session: StoreGenerationSession?
    weak var context: ModelContext?
    weak var container: ModelContainer? {
        didSet { if container != nil { returnedContainerObserved = true } }
    }

    var constructionInProgress = false
    var constructorStarted = false
    private var returnedContainerObserved = false

    init(_ session: StoreGenerationSession) {
        self.session = session
        context = session.modelContext
        container = session.modelContext.container
        returnedContainerObserved = true
    }

    init() { constructionInProgress = true }

#if DEBUG
    func completeCompletedAbortContextConstruction(_ value: ModelContainer) throws {
        guard constructionInProgress, context == nil, session == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        container = value
        context = value.mainContext
        constructorStarted = true
        returnedContainerObserved = true
        constructionInProgress = false
    }
#endif

#if DEBUG
    /// Fixed scalar diagnostics only; this never grants drain or retains a model.
    fileprivate var constructorReturnUnobservedForTesting: Bool {
        constructorStarted && !returnedContainerObserved
    }
#endif

    var isDrained: Bool {
        !constructionInProgress && (!constructorStarted || returnedContainerObserved)
            && session == nil && context == nil && container == nil
    }
}

/// Captures exact leases while the owning sessions are still alive. It stores
/// no factory, callback, arbitrary Error, writer or strong SwiftData reference.
/// The owner must retain this inventory on every failure until handoff closes
/// its captured handles. Sealing is a one-way transfer, not proof of drain.
@MainActor
final class EraseReaderRetirementInventoryV1 {
    private var observations: [EraseSessionWeakObservationV1] = []
    private var readers: [GenerationLeaseHandleV1] = []
    private var allocations: [GenerationLeaseAllocationAttemptV1] = []
    private var sealedWitness: EraseSessionDrainWitnessV1?
    private var freshAdoptionWitness: EraseFreshAdoptionDrainWitnessV1?
    private var admissionClosed = false
    private weak var freshOwner: EraseFreshAdoptionOwnerV1?
    private var freshOwnerWasBound = false
    private weak var preparationOperation: EraseRouterOperationV1?
    private var preparationWasBound = false
    private var preparationWitness: ErasePreparationFailureDrainWitnessV1?
#if DEBUG
    private var originalShutdownWitness: EraseOriginalShutdownWitnessV1?
    // Retains any uncertain diagnostic descriptor through the Erase operation.
    let sourceProtectionDiagnosticIO = EraseAbortCheckedSnapshotIOV1()
#endif
    private weak var coldPreparationOperation: EraseColdPreparationOperationV1?
    private var coldPreparationWasBound = false
    // Bound only by a future exact C05 reader admission. A nil activity must
    // never fall back to ordinary cold-reader publication for a C05 source.
    private var frozenC05ReaderActivity: GenerationTemporalActivityHandleV1?
    private var coldC05SuccessWitness: EraseC05ColdSourceDrainWitnessV1?
    private var originalObservationCount = 0
    private var originalReaders: [GenerationLeaseHandleV1] = []
    private var abortedOriginalReaderRetirementArmed = false
#if DEBUG
    private var completedAbortOriginalShutdownArmed = false
#endif
#if DEBUG
    private(set) var lastAbortResourceCensusForTesting = "not-checked"

    private func abortResourceCensusForTesting() -> String {
        let original = observations.prefix(originalObservationCount)
        let preparation = observations.dropFirst(originalObservationCount)
        return "observations=\(observations.count) original=\(original.count)"
            + " originalUndrained=\(original.filter { !$0.isDrained }.count)"
            + " preparation=\(preparation.count)"
            + " preparationUndrained=\(preparation.filter { !$0.isDrained }.count)"
            + " inProgress=\(observations.filter { $0.constructionInProgress }.count)"
            + " started=\(observations.filter { $0.constructorStarted }.count)"
            + " liveSession=\(observations.filter { $0.session != nil }.count)"
            + " liveContext=\(observations.filter { $0.context != nil }.count)"
            + " liveContainer=\(observations.filter { $0.container != nil }.count)"
            + " allocations=\(allocations.count) readers=\(readers.count)"
    }
#endif

    func bindColdPreparation(operation: EraseColdPreparationOperationV1) throws {
        try requireUnsealed()
        guard !coldPreparationWasBound, !preparationWasBound, !freshOwnerWasBound,
              observations.isEmpty, readers.isEmpty, allocations.isEmpty else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try operation.requireInventoryBinding(self)
        coldPreparationOperation = operation
        coldPreparationWasBound = true
    }

    func containsColdPreparationAllocation(_ value: GenerationLeaseAllocationAttemptV1) -> Bool {
        coldPreparationWasBound && allocations.contains(where: { $0 === value })
    }

    func requireColdPreparationCensus(_ leases: [GenerationLeaseTokenV1],
        registry: GenerationLeaseRegistryV1) throws {
        try requireUnsealed()
        guard coldPreparationWasBound, coldPreparationOperation != nil,
              allocations.allSatisfy({ $0.matches(registry: registry) }) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let expected = allocations.compactMap(\.coldPreparationPublishedToken)
        guard expected.allSatisfy({ $0.role == .reader }),
              Set(expected.map(\.leaseID)).count == expected.count,
              leases.count == expected.count, leases.allSatisfy({ expected.contains($0) }) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }

    func sealForColdPreparationFailure(operation: EraseColdPreparationOperationV1,
        registry: GenerationLeaseRegistryV1) throws -> EraseColdPreparationFailureDrainWitnessV1 {
        try requireUnsealed()
        guard coldPreparationOperation === operation,
              observations.allSatisfy({ !$0.constructionInProgress }),
              allocations.allSatisfy({ $0.matches(registry: registry) }) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try operation.requireFailureWitnessRegistration(inventory: self, registry: registry)
        admissionClosed = true
        allocations.forEach { $0.sealForRetirement() }
        return EraseColdPreparationFailureDrainWitnessV1(operation: operation, registry: registry,
            observations: observations, readers: allocations)
    }

    /// Successful C05 source retirement is separate from the failure-only
    /// disposal witness. The actual weak SwiftData aliases must be gone
    /// before closing admission or releasing any source lease token.
    func sealForColdC05SourceDrain(
        operation: EraseColdPreparationOperationV1,
        registry: GenerationLeaseRegistryV1,
        expected: ErasePreparationV2
    ) throws -> EraseC05ColdSourceDrainWitnessV1 {
        try requireUnsealed()
        guard coldPreparationOperation === operation,
              coldC05SuccessWitness == nil,
              expected.c05JobDrainV3?.phase == .drained,
              observations.allSatisfy({ $0.isDrained }),
              allocations.allSatisfy({ $0.matches(registry: registry) }) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        _ = try operation.requireC05ColdPhase(expected, phase: .drained)
        let witness = EraseC05ColdSourceDrainWitnessV1(
            operation: operation, registry: registry,
            inventory: self, observations: observations,
            readers: allocations)
        admissionClosed = true
        allocations.forEach { $0.sealForRetirement() }
        coldC05SuccessWitness = witness
        return witness
    }

    func requireColdC05SourceCensus(
        _ leases: [GenerationLeaseTokenV1],
        registry: GenerationLeaseRegistryV1,
        witness: EraseC05ColdSourceDrainWitnessV1
    ) throws {
        guard coldC05SuccessWitness === witness else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try witness.requireDrained(registry: registry)
        let expected = allocations.compactMap(\.coldPreparationPublishedToken)
        guard leases.count == expected.count,
              leases.allSatisfy({ expected.contains($0) }) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }

    func bindPreparation(operation: EraseRouterOperationV1) throws {
        try requireUnsealed()
        guard !preparationWasBound, !freshOwnerWasBound, !coldPreparationWasBound, allocations.isEmpty else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try operation.requirePreparationInventoryBinding(self)
        originalObservationCount = observations.count
        originalReaders = readers
        preparationOperation = operation
        preparationWasBound = true
    }

    func requirePreparationCensus(_ leases: [GenerationLeaseTokenV1],
        registry: GenerationLeaseRegistryV1, sourceWriter: GenerationLeaseHandleV1,
        writer: GenerationWriterAllocationAttemptV1?,
        checkedOriginalRecovery: Bool = false) throws {
        var expected: [GenerationLeaseTokenV1] = []
#if DEBUG
        var diagnosticStage = "unsealed"
#endif
        do {
            try requireUnsealed()
#if DEBUG
            diagnosticStage = "binding"
#endif
            guard preparationWasBound, preparationOperation != nil,
                  allocations.allSatisfy({ $0.matches(registry: registry) }),
                  writer.map({ $0.matches(registry: registry) }) ?? true else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
#if DEBUG
            diagnosticStage = "source-writer"
#endif
            if checkedOriginalRecovery {
                // The caller holds its original-ticket checked EX/G and has
                // just decoded the exact durable lease census. Wrapper
                // liveness/provider identity is pure object state here.
                try sourceWriter.requireExactRegistry(registry)
            } else {
                try sourceWriter.requireLiveTemporalIdentity(mutationRegistry: registry)
            }
#if DEBUG
            diagnosticStage = "original-readers"
#endif
            for reader in originalReaders {
                if checkedOriginalRecovery {
                    try reader.requireExactRegistry(registry)
                } else {
                    try reader.requireLiveTemporalIdentity(mutationRegistry: registry)
                }
            }
            expected = originalReaders.map(\.token) + [sourceWriter.token]
            expected += allocations.compactMap(\.preparationPublishedToken)
            if let token = writer?.preparationPublishedToken { expected.append(token) }
#if DEBUG
            diagnosticStage = "lease-set"
#endif
            guard Set(expected.map(\.leaseID)).count == expected.count,
                  leases.count == expected.count,
                  leases.allSatisfy({ expected.contains($0) }) else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
        } catch {
#if DEBUG
            let expectedReaders = expected.filter { $0.role == .reader }.count
            let expectedWriters = expected.filter { $0.role == .writer }.count
            let observedReaders = leases.filter { $0.role == .reader }.count
            let observedWriters = leases.filter { $0.role == .writer }.count
            FileHandle.standardError.write(Data((
                "ERASE_PREPARATION_CENSUS_V1 stage=\(diagnosticStage)"
                    + " errorType=\(String(reflecting: type(of: error)))"
                    + " originalReaders=\(originalReaders.count)"
                    + " allocations=\(allocations.count)"
                    + " expected=\(expected.count) expectedReaders=\(expectedReaders)"
                    + " expectedWriters=\(expectedWriters) observed=\(leases.count)"
                    + " observedReaders=\(observedReaders) observedWriters=\(observedWriters)\n"
            ).utf8))
#endif
            throw error
        }
    }

    func containsPreparationAllocation(_ value: GenerationLeaseAllocationAttemptV1) -> Bool {
        preparationWasBound && allocations.contains(where: { $0 === value })
    }

    func observesPreparationSession(_ value: StoreGenerationSession) -> Bool {
        preparationWasBound && observations.dropFirst(originalObservationCount).contains(where: {
            $0.session === value && $0.context === value.modelContext && !$0.constructionInProgress
        })
    }

    func sealForPreparationFailure(operation: EraseRouterOperationV1,
        registry: GenerationLeaseRegistryV1,
        writer: GenerationWriterAllocationAttemptV1?) throws -> ErasePreparationFailureDrainWitnessV1 {
        guard preparationOperation === operation, preparationWitness == nil,
              !admissionClosed, sealedWitness == nil,
              observations.allSatisfy({ !$0.constructionInProgress }),
              allocations.allSatisfy({ $0.matches(registry: registry) }),
              writer.map({ $0.matches(registry: registry) }) ?? true else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try operation.requirePreparationFailureWitnessRegistration(inventory: self, registry: registry, writer: writer)
        admissionClosed = true
        allocations.forEach { $0.sealForRetirement() }
        writer?.sealForRetirement()
        let result = ErasePreparationFailureDrainWitnessV1(operation: operation, registry: registry,
            observations: Array(observations.dropFirst(originalObservationCount)),
            readers: allocations, writer: writer)
        preparationWitness = result
        return result
    }

#if DEBUG
    /// The original Service has already sealed and checked-disposed its
    /// preparation cohort before issuing a genuine no-effect abort receipt.
    /// While that exact operation is still current, bind the disposed witness
    /// to the original-reader cohort. Admission stays closed throughout.
    func armCompletedAbortOriginalShutdownAfterDisposal(
        operation: EraseRouterOperationV1,
        registry: GenerationLeaseRegistryV1,
        witness: ErasePreparationFailureDrainWitnessV1?,
        writer: GenerationWriterAllocationAttemptV1?
    ) throws {
        guard preparationOperation === operation, preparationWasBound,
              !completedAbortOriginalShutdownArmed,
              originalShutdownWitness == nil, sealedWitness == nil,
              originalObservationCount > 0, !originalReaders.isEmpty,
              originalReaders.allSatisfy({ original in
                  readers.contains(where: { $0 === original })
              }),
              observations.allSatisfy({ !$0.constructionInProgress }),
              allocations.allSatisfy({ $0.matches(registry: registry) }),
              writer.map({ $0.matches(registry: registry) }) ?? true else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        if let witness {
            guard admissionClosed, preparationWitness === witness else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try witness.requireDisposed()
        } else {
            guard !admissionClosed, preparationWitness == nil,
                  writer == nil else {
                throw GenerationLeaseRegistryFailureV1.uncertainOwner
            }
            try requireNoConstructedResourcesForAbort()
        }
        completedAbortOriginalShutdownArmed = true
    }

    /// Seals the actual original and preparation inventory together. The
    /// preparation-failure witness deliberately excludes original readers and
    /// therefore cannot authorize this test-host shutdown.
    func sealForOriginalShutdown(operation: EraseRouterOperationV1,
        registry: GenerationLeaseRegistryV1,
        writer: GenerationWriterAllocationAttemptV1?) throws
        -> EraseOriginalShutdownWitnessV1 {
        let unsealed = !admissionClosed && preparationWitness == nil
        let disposedAbort = completedAbortOriginalShutdownArmed
            && admissionClosed && preparationWitness != nil
        guard preparationOperation === operation, originalShutdownWitness == nil,
              (unsealed || disposedAbort), sealedWitness == nil,
              observations.allSatisfy({ !$0.constructionInProgress }),
              allocations.allSatisfy({ $0.matches(registry: registry) }),
              writer.map({ $0.matches(registry: registry) }) ?? true else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try operation.requireOriginalShutdownInventoryRegistration(
            inventory: self, registry: registry, writer: writer)
        admissionClosed = true
        allocations.forEach { $0.sealForRetirement() }
        writer?.sealForRetirement()
        let result = EraseOriginalShutdownWitnessV1(operation: operation,
            registry: registry, observations: observations,
            originalReaders: originalReaders, capturedReaders: readers,
            readers: allocations, writer: writer)
        originalShutdownWitness = result
        return result
    }
#endif

    func bindFreshAdoption(owner: EraseFreshAdoptionOwnerV1) throws {
        try requireUnsealed()
        guard !freshOwnerWasBound, !preparationWasBound, !coldPreparationWasBound else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try owner.requireReaderInventoryBinding(self)
        freshOwner = owner
        freshOwnerWasBound = true
    }

    fileprivate func registerFreshRegistry(_ registry: GenerationLeaseRegistryV1,
        factory: StoreGenerationFactory) throws {
        if coldPreparationWasBound {
            guard let coldPreparationOperation else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try coldPreparationOperation.registerRegistry(registry, factory: factory, inventory: self)
        }
        if preparationWasBound {
            guard let preparationOperation else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try preparationOperation.registerPreparationRegistry(registry, factory: factory, inventory: self)
        }
        guard freshOwnerWasBound else { return }
        guard let freshOwner else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
        try freshOwner.registerReaderRegistry(registry, inventory: self, factory: factory)
    }

    fileprivate func requireUnsealed() throws {
        guard !admissionClosed, sealedWitness == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }

    /// Register before token publication so partial publication, wrapper and
    /// outer-postcheck failures retain their actual allocation owner.
    func retainAllocation(_ allocation: GenerationLeaseAllocationAttemptV1) throws {
        try requireUnsealed()
        guard !allocations.contains(where: { $0 === allocation }) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        if freshOwnerWasBound {
            guard let freshOwner else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            try freshOwner.retainReaderAllocation(allocation, inventory: self)
        }
        allocations.append(allocation)
    }

    fileprivate func acquireCapturedReader(_ allocation: GenerationLeaseAllocationAttemptV1) throws
        -> GenerationLeaseHandleV1 {
        try requireUnsealed()
        guard allocations.contains(where: { $0 === allocation }) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        if coldPreparationWasBound {
            guard let coldPreparationOperation else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            if let frozenC05ReaderActivity {
                return try allocation.acquireReaderForFrozenC05ColdErase(
                    operation: coldPreparationOperation,
                    activity: frozenC05ReaderActivity)
            }
            try coldPreparationOperation.requireOrdinaryColdReaderAdmission()
            return try allocation.acquireReaderForColdErasePreparation(operation: coldPreparationOperation)
        }
        guard frozenC05ReaderActivity == nil else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        if freshOwnerWasBound {
            guard let freshOwner else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            return try allocation.acquireReaderForEraseFreshAdoption(adoption: freshOwner)
        }
        if preparationWasBound {
            guard let preparationOperation else { throw GenerationLeaseRegistryFailureV1.uncertainOwner }
            return try allocation.acquireReaderForErasePreparation(operation: preparationOperation)
        }
        return try allocation.acquireReader()
    }

    /// Capture happens immediately after lease acquisition, before container
    /// construction can throw. The factory ends this scope synchronously; a
    /// still-running construction cannot become a drain witness.
    fileprivate func beginConstruction(reader: GenerationLeaseHandleV1?) throws
        -> EraseSessionWeakObservationV1 {
        try requireUnsealed()
        let observation = EraseSessionWeakObservationV1()
        observations.append(observation)
        if let reader, !readers.contains(where: { $0 === reader }) {
            readers.append(reader)
        }
        return observation
    }

    func capture(_ session: StoreGenerationSession) throws {
        try requireUnsealed()
        guard !observations.contains(where: { $0.session === session }) else { return }
        observations.append(EraseSessionWeakObservationV1(session))
        if let reader = session.eraseRetirementReaderHandle,
           !readers.contains(where: { $0 === reader }) {
            readers.append(reader)
        }
    }

#if DEBUG
    /// Returns the actual source reader captured before Erase preparation. A
    /// token alone cannot identify its retained wrapper or original session.
    func capturedOriginalReaderForV949Fixture(
        session: StoreGenerationSession,
        operation: EraseRouterOperationV1,
        registry: GenerationLeaseRegistryV1,
        sealedDrain: EraseSessionDrainWitnessV1?
    ) throws -> GenerationLeaseHandleV1 {
        guard preparationWasBound, preparationOperation === operation,
              let reader = session.eraseRetirementReaderHandle,
              let token = session.readerLeaseToken,
              reader.token == token, token.role == .reader,
              token.epoch.generationID == session.generationID,
              originalReaders.contains(where: { $0 === reader }) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        let capturedOriginal: Bool
        if let sealedDrain {
            // seal(binding:) moved the original aliases into this exact
            // witness and cleared the inventory's mutable arrays.
            capturedOriginal = admissionClosed && sealedWitness === sealedDrain
                && sealedDrain.capturedOriginalReaderForV949Fixture(
                    session: session, reader: reader)
        } else {
            capturedOriginal = !admissionClosed && sealedWitness == nil
                && readers.contains(where: { $0 === reader })
                && observations.prefix(originalObservationCount).contains(where: {
                    $0.session === session && $0.context === session.modelContext
                        && $0.container === session.modelContext.container
                        && !$0.constructionInProgress
                })
        }
        guard capturedOriginal else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try reader.requireLiveTemporalIdentity(mutationRegistry: registry)
        return reader
    }
#endif

    func requireNoConstructedResourcesForAbort() throws {
        // Original source capture does not allocate a reader. Any actual
        // allocation remains owned until the separate preparation-failure
        // disposal boundary has genuinely settled it.
#if DEBUG
        lastAbortResourceCensusForTesting = abortResourceCensusForTesting()
#endif
        guard !admissionClosed, allocations.isEmpty,
              observations.allSatisfy({ !$0.constructionInProgress && (!$0.constructorStarted || $0.isDrained) }) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }

    /// Cancellation records the already-checked no-effect preparation boundary
    /// while its actual operation is still current.  The original cohort is
    /// deliberately not closed here: its SwiftData aliases may still be live.
    func armAbortedOriginalReaderRetirement(operation: EraseRouterOperationV1) throws {
        guard preparationOperation === operation, preparationWasBound,
              !abortedOriginalReaderRetirementArmed,
              originalObservationCount > 0, !originalReaders.isEmpty,
              originalReaders.allSatisfy({ original in
                  readers.contains(where: { $0 === original })
              }) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        if let preparationWitness {
            try preparationWitness.requireDisposed()
        } else {
            try requireNoConstructedResourcesForAbort()
        }
        abortedOriginalReaderRetirementArmed = true
    }

    /// The Router calls this only after the exact old writer has been checked
    /// closed.  A live original session/context/container leaves every reader
    /// retained for a later retry; close never relies on wrapper destruction.
    func closeAbortedOriginalReadersAfterDrain() throws {
        guard abortedOriginalReaderRetirementArmed,
              observations.prefix(originalObservationCount).allSatisfy({ $0.isDrained }),
              originalReaders.allSatisfy({ original in
                  readers.contains(where: { $0 === original })
              }) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        for original in originalReaders { try original.close() }
    }

    /// A pre-intent Erase may keep the original owner and source readers while
    /// proving the prepared target absent. No target or unknown lease may
    /// survive the first destructive target step.
    func requireSourceOnlyPreparationForAbort(
        sourceEpoch: GenerationEpochV1,
        registry: GenerationLeaseRegistryV1
    ) throws {
        try requireUnsealed()
        guard preparationWasBound, preparationOperation != nil,
              originalObservationCount <= observations.count,
              observations.dropFirst(originalObservationCount).allSatisfy({ $0.isDrained }),
              allocations.allSatisfy({
                  $0.matches(registry: registry) && $0.generationEpoch == sourceEpoch
              }),
              readers.allSatisfy({ reader in
                  originalReaders.contains(where: { $0 === reader })
                      || allocations.contains(where: { $0.allocatedHandle === reader })
              }) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
    }

    func sealForFreshAdoptionFailure(owner: EraseFreshAdoptionOwnerV1,
        registry: GenerationLeaseRegistryV1,
        writerAllocation: GenerationWriterAllocationAttemptV1?) throws -> EraseFreshAdoptionDrainWitnessV1 {
        guard !admissionClosed, sealedWitness == nil, freshAdoptionWitness == nil,
              observations.allSatisfy({ !$0.constructionInProgress }),
              allocations.allSatisfy({ $0.matches(registry: registry) }),
              readers.allSatisfy({ reader in allocations.contains(where: { $0.allocatedHandle === reader }) }),
              writerAllocation.map({ $0.matches(registry: registry) }) ?? true else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        try owner.requireFailureWitnessRegistration(inventory: self, registry: registry,
            writerAllocation: writerAllocation)
        admissionClosed = true
        for allocation in allocations { allocation.sealForRetirement() }
        writerAllocation?.sealForRetirement()
        let witness = EraseFreshAdoptionDrainWitnessV1(owner: owner, registry: registry,
            observations: observations, readers: allocations, writer: writerAllocation)
        freshAdoptionWitness = witness
        return witness
    }

    func seal(binding: EraseRetirementBindingV1) throws -> EraseSessionDrainWitnessV1 {
        guard !admissionClosed, sealedWitness == nil,
              (!observations.isEmpty || !allocations.isEmpty),
              observations.allSatisfy({ !$0.constructionInProgress }) else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        // Monotonic admission closure only. Actual drain and physical close
        // remain independently checked by the transferred exclusion.
        admissionClosed = true
        for allocation in allocations { allocation.sealForRetirement() }
        let witness = EraseSessionDrainWitnessV1(binding: binding,
            observations: observations, originalObservationCount: originalObservationCount,
            readers: readers, allocations: allocations)
        sealedWitness = witness
        observations.removeAll()
        readers.removeAll()
        allocations.removeAll()
        return witness
    }
}

