    private static func makeLiveWorkspaceIdentity() -> WorkspaceReplicaIdentityV1 {
        for _ in 0..<16 {
            let workspaceID = WorkspaceID()
            let replicaID = ReplicaID()
            if let identity = try? WorkspaceReplicaIdentityV1(
                workspaceID: workspaceID,
                replicaID: replicaID
            ) {
                return identity
            }
        }
        preconditionFailure("Unable to create distinct workspace and replica identities")
    }

    private func forSaveReproof() -> StoreGenerationFactory {
        // The fixed closure below only reproves this session's generation.
        // Allocation ownership stays with the actual operation inventory;
        // saving must not extend that inventory's lifetime through a factory.
        var reproof = withoutColdOpenDiagnostics()
        reproof.eraseReaderRetirementInventory = nil
        return reproof
    }

    /// Bind the already retained cold Registry to this exact Factory provider
    /// before constructing a live target session. A different cached Registry
    /// is an alias conflict, not permission to reconstruct a second owner.
    @MainActor
    func bindingExistingSchema2ColdRegistry(
        _ registry: GenerationLeaseRegistryV1,
        operation: EraseColdPreparationOperationV1
    ) throws -> StoreGenerationFactory {
        try operation.requireConstructedSchema2ColdRegistry(registry)
        try generationLeaseRegistryProvider.bindExistingForSchema2Cold(registry)
        let bound = forSaveReproof()
        guard try bound.makeGenerationLeaseRegistry() === registry else {
            throw GenerationLeaseRegistryFailureV1.uncertainOwner
        }
        return bound
    }

    private func withoutColdOpenDiagnostics() -> StoreGenerationFactory {
#if DEBUG
        var copy = self
        copy.coldOpenDiagnosticForTesting = false
        copy.coldOpenFixedDiagnosticsForTesting = false
        return copy
#else
        return self
#endif
    }

#if DEBUG
    private func coldOpenDiagnostic(_ phase: String) {
        guard coldOpenDiagnosticForTesting || coldOpenFixedDiagnosticsForTesting else { return }
        let uptime = String(format: "%.6f", ProcessInfo.processInfo.systemUptime)
        FileHandle.standardError.write(Data(
            ("StoreGenerationFactory cold-open phase=" + phase
                + " uptimeSeconds=" + uptime + "\n").utf8
        ))
    }
#endif

