    @MainActor
    private func switchCurrentGenerationLocked(
        expected oldID: UUID,
        to newID: UUID,
        authority: StoreRestoreGenerationAuthority
    ) throws {
        let envelope = try decodeCurrentPointer(
            at: dataRootURL.appendingPathComponent(Self.currentPointerName)
        )
        switch envelope {
        case .legacy:
            let pointer = try makeRestoreCurrentPointer(
                expectedOldID: oldID,
                newID: newID
            )
            try authority.switchCurrentGeneration(
                expected: oldID,
                to: newID,
                pointer: pointer,
                expectedCurrentPointerData: envelope.data
            )
        case .v2:
            let pointer = try makeRestoreCurrentPointer(
                expectedOldID: oldID,
                newID: newID
            )
            try authority.switchCurrentGeneration(
                expected: oldID,
                to: newID,
                pointer: pointer,
                expectedCurrentPointerData: envelope.data
            )
        case .v3(let current, _):
            let history = try current.knownReplicaIdentitySet()
            let prepared = try makeRestoreCurrentPointer(
                expectedOldID: oldID,
                newID: newID
            ).generationManifestSHA256
            let pointer = try makeRestoreCurrentPointerV3(
                expectedOldID: oldID,
                newID: newID,
                identity: try current.identity(),
                knownReplicaIDs: history,
                preparedGenerationManifestSHA256: prepared
            )
            try authority.switchCurrentGeneration(
                expected: oldID,
                to: newID,
                pointer: pointer,
                expectedCurrentPointer: current
            )
        }
        guard try currentGenerationID(authority: authority) == newID else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
    }

    @MainActor
    func switchCurrentGeneration(
        expected oldID: UUID,
        to newID: UUID,
        expectedCurrentPointer: CurrentGenerationPointerV3,
        identity: WorkspaceReplicaIdentityV1,
        sourceReplicaID: ReplicaID? = nil,
        knownReplicaIDs: Set<ReplicaID> = [],
        preparedGenerationManifestSHA256: String,
        restoreProof: StoreRestoreGenerationManifestProofV1? = nil,
        restoreFileSnapshot: StoreRestoreGenerationFileSnapshotV1? = nil,
        authority: StoreRestoreGenerationAuthority,
        publicationValidation: () throws -> Void = {},
        publicationScope: (_ publishPointer: () throws -> Void) throws -> Void = { try $0() }
    ) throws {
        let registry = try makeGenerationLeaseRegistry()
        try registry.withNoMigrationReservation {
            try switchCurrentGenerationLocked(
                expected: oldID,
                to: newID,
                expectedCurrentPointer: expectedCurrentPointer,
                identity: identity,
                sourceReplicaID: sourceReplicaID,
                knownReplicaIDs: knownReplicaIDs,
                preparedGenerationManifestSHA256:
                    preparedGenerationManifestSHA256,
                restoreProof: restoreProof,
                restoreFileSnapshot: restoreFileSnapshot,
                authority: authority,
                publicationValidation: publicationValidation,
                publicationScope: publicationScope
            )
        }
    }

    @MainActor
    private func switchCurrentGenerationLocked(
        expected oldID: UUID,
        to newID: UUID,
        expectedCurrentPointer: CurrentGenerationPointerV3,
        identity: WorkspaceReplicaIdentityV1,
        sourceReplicaID: ReplicaID?,
        knownReplicaIDs: Set<ReplicaID>,
        preparedGenerationManifestSHA256: String,
        restoreProof: StoreRestoreGenerationManifestProofV1?,
        restoreFileSnapshot: StoreRestoreGenerationFileSnapshotV1?,
        authority: StoreRestoreGenerationAuthority,
        publicationValidation: () throws -> Void,
        publicationScope: (_ publishPointer: () throws -> Void) throws -> Void
    ) throws {
        guard expectedCurrentPointer.generationID == canonicalString(for: oldID),
              try currentGenerationPointerV3(
                  expectedGenerationID: oldID,
                  authority: authority
              ) == expectedCurrentPointer else {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        guard sourceReplicaID != identity.replicaID else {
            throw WorkspaceIdentityFailure.roleCollision
        }
        var history = knownReplicaIDs
        if let sourceReplicaID { history.insert(sourceReplicaID) }
        let pointer = try makeRestoreCurrentPointerV3(
            expectedOldID: oldID,
            newID: newID,
            identity: identity,
            knownReplicaIDs: history,
            preparedGenerationManifestSHA256:
                preparedGenerationManifestSHA256,
            restoreProof: restoreProof,
            restoreFileSnapshot: restoreFileSnapshot
        )
        if pointer.generationManifestSHA256 != preparedGenerationManifestSHA256 {
            throw StoreGenerationFailure.dataPointerInvalid
        }
        // G remains outermost. A staging owner may hold R while invoking the
        // nonescaping pointer operation, closing the proof-to-visibility gap.
        // Catching a failed or repeated invocation cannot manufacture success.
        var invocations = 0
        var published = false
        // The existing synchronous scope cannot retain either callback.
        try withoutActuallyEscaping(publicationValidation) { validatePublication in
            try publicationScope {
                invocations += 1
                guard invocations == 1 else { throw StoreGenerationFailure.dataPointerInvalid }
                try validatePublication()
                if let restoreProof {
                    guard let restoreFileSnapshot,
                          restoreFileSnapshot.restoreProof == restoreProof else {
                        throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
                    }
                    try authority.switchCurrentGeneration(
                        expected: oldID,
                        to: newID,
                        pointer: pointer,
                        expectedCurrentPointer: expectedCurrentPointer,
                        restoreFileSnapshot: restoreFileSnapshot
                    )
                } else {
                    guard restoreFileSnapshot == nil else {
                        throw StoreMigrationFailure.maintenanceRequired(.targetMismatch)
                    }
                    try authority.switchCurrentGeneration(
                        expected: oldID,
                        to: newID,
                        pointer: pointer,
                        expectedCurrentPointer: expectedCurrentPointer
                    )
                }
                guard try currentGenerationID(authority: authority) == newID,
                      try currentWorkspaceIdentity(
                          expectedGenerationID: newID,
                          authority: authority
                      ) == identity else {
                    throw StoreGenerationFailure.dataPointerInvalid
                }
                published = true
            }
        }
        guard invocations == 1, published else { throw StoreGenerationFailure.dataPointerInvalid }
    }

